  ('spell.air_bubble', 'Bolha de Ar', 'Air Bubble', 'Burbuja de aire', 'Reage quando uma criatura não consegue respirar, envolvendo sua cabeça em ar puro por pouco tempo.', 'Reacts when a creature cannot breathe, surrounding its head with clean air for a short time.', 'Reacciona cuando una criatura no puede respirar y rodea su cabeza con aire puro por un breve período.', 1, FALSE, FALSE, ARRAY['arcane', 'divine', 'primal']::text[], 'reaction', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 319, '{"heightened":null,"needs_review":false}'::jsonb),
