  ('spell.spiritual_armament', 'Armamento Espiritual', 'Spiritual Armament', 'Armamento espiritual', 'Cria um eco fantasmagórico de uma arma para atacar uma criatura e repetir o ataque ao Sustentar a magia.', 'Creates a ghostly echo of a weapon to attack a creature and repeat the attack when Sustained.', 'Crea un eco fantasmal de un arma para atacar a una criatura y repetir el ataque al Mantener el conjuro.', 2, FALSE, FALSE, ARRAY['divine', 'occult']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 317, '{"heightened":null,"needs_review":false}'::jsonb),
