  ('spell.blur', 'Borrar', 'Blur', 'Desenfoque', 'Distorce a silhueta de uma criatura, concedendo a condição ocultado por um curto período.', 'Distorts a creature''s silhouette, granting it the concealed condition for a short time.', 'Distorsiona la silueta de una criatura y le concede la condición oculto durante un breve tiempo.', 2, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 321, '{"heightened":null,"needs_review":false}'::jsonb),
