  ('spell.summon_dragon', 'Convocar Dragão', 'Summon Dragon', 'Convocar dragón', 'Conjura um dragão de nível apropriado para lutar por você durante a duração sustentada.', 'Summons an appropriately leveled dragon to fight for you while Sustained.', 'Convoca un dragón del nivel apropiado para luchar por ti mientras se mantiene.', 5, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult', 'primal']::text[], 'three-actions', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 326, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core_2.ansias_de_carnical', 'Ânsias de Carníçal', 'Carnivore''s Craving', 'Ansias de carnívoro', 'Magia de 2º ranque, divina ou ocultista: aflige uma criatura tocada com fome de carne crua e aplica enjoado conforme o salvamento de Vontade.', '2nd-rank divine or occult spell: afflicts a touched creature with a craving for raw meat and applies sickened based on its Will save.', 'Conjuro divino u ocultista de rango 2: aflige a una criatura tocada con hambre de carne cruda y aplica nauseado según su salvación de Voluntad.', 2, FALSE, FALSE, ARRAY['divine', 'occult']::text[], 2, 'toque', '1 criatura', 'varia', 'Vontade', ARRAY['Concentração', 'Maldição', 'Manuseio', 'Mental']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 240, '{"heightened":null,"mechanics":{"criticalSuccess":"não afetado","success":"enjoado 1","failure":"enjoado 2; não pode reduzir abaixo de enjoado 1 até consumir carne crua","criticalFailure":"como falha, mas não pode reduzir abaixo de enjoado 2 até consumir carne crua"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.arma_do_julgamento', 'Arma do Julgamento', 'Weapon of Judgment', 'Arma del juicio', 'Magia divina santificada de 9º ranque: invoca uma arma espiritual que ataca conforme a escolha guerra ou paz, causando 4d10 de dano com ataque mágico.', '9th-rank sanctified divine spell: summons a spiritual weapon that attacks according to a war or peace choice, dealing 4d10 damage with a spell attack.', 'Conjuro divino santificado de rango 9: invoca un arma espiritual que ataca según la elección de guerra o paz y causa 4d10 de daño con un ataque mágico.', 9, FALSE, FALSE, ARRAY['divine']::text[], 2, '30 metros', '1 criatura', '1 minuto', NULL, ARRAY['Concentração', 'Espírito', 'Manuseio', 'Santificado']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 240, '{"heightened":null,"mechanics":{"attack":"arma flutuante faz Golpes reativos conforme guerra ou paz","attackModifier":"modificador de ataque com magia","damage":"4d10; tipo igual ao da arma escolhida, ou espiritual se for mais prejudicial","multipleAttackPenalty":"separada da sua e aumenta durante o turno do alvo","heightened":"+1d10 no 10º ranque"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.arvore_protetora', 'Árvore Protetora', 'Protective Tree', 'Árbol protector', 'Magia primal de 1º ranque: faz uma árvore Média proteger aliados adjacentes, absorvendo primeiro o dano de Golpes.', '1st-rank primal spell: creates a Medium tree that protects adjacent allies by taking Strike damage first.', 'Conjuro primigenio de rango 1: crea un árbol Mediano que protege a aliados adyacentes recibiendo primero el daño de los Golpes.', 1, FALSE, FALSE, ARRAY['primal']::text[], 2, '9 metros', NULL, '1 minuto', NULL, ARRAY['Concentração', 'Madeira', 'Manuseio', 'Planta']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 241, '{"heightened":null,"mechanics":{"tree":{"size":"Médio","ac":10,"hp":10},"interception":"quando aliado adjacente é atingido por Golpe, a árvore recebe o dano primeiro; excesso passa ao alvo","persistence":"se sobreviver em terra até o fim, permanece como árvore mundana","heightened":"+10 PV por ranque acima do 1º"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.bolha_na_pele', 'Bolha na Pele', 'Skin Bubble', 'Burbuja en la piel', 'Magia de 5º ranque, arcana, ocultista ou primal: cria bolhas ácidas na pele de uma criatura e permite estourá-las em um cone de 4,5 metros.', '5th-rank arcane, occult, or primal spell: creates acidic skin bubbles on a creature and lets you burst them in a 4.5-meter cone.', 'Conjuro arcano, ocultista o primigenio de rango 5: crea burbujas ácidas en la piel de una criatura y permite reventarlas en un cono de 4,5 metros.', 5, FALSE, FALSE, ARRAY['arcane', 'occult', 'primal']::text[], 2, '18 metros', '1 criatura', '1 minuto', 'Fortitude', ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 241, '{"heightened":null,"mechanics":{"criticalSuccess":"não afetado","success":"1 bolha; pode gastar 1 ação de concentração para estourá-la","failure":"2 bolhas","criticalFailure":"4 bolhas","burst":"alvo e criaturas em cone de 4,5 metros sofrem 7d6 de ácido, Fortitude básico","heightened":"+1d6 no dano por bolha por ranque"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.aspecto_triplo', 'Aspecto Triplo', 'Triple Form', 'Aspecto triple', 'Magia de 3º ranque, ocultista ou primal: permite alternar entre três idades autênticas, concedendo +4 de estado em Dissimulação para parecer ter a idade escolhida.', '3rd-rank occult or primal spell: lets you shift between three authentic ages, granting a +4 status bonus to Deception checks to pass as the chosen age.', 'Conjuro ocultista o primigenio de rango 3: permite alternar entre tres edades auténticas y concede +4 de estado a Dissimulación para aparentar la edad elegida.', 3, FALSE, FALSE, ARRAY['occult', 'primal']::text[], 1, NULL, NULL, 'até a próxima preparação diária', NULL, ARRAY['Concentração', 'Manuseio', 'Morfia']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 241, '{"heightened":null,"mechanics":{"forms":["donzela","mãe","matriarca","idade natural"],"switching":"pode mudar de idade ao Sustentar a magia","disguiseBonus":"+4 status em Dissimulação para passar pela idade escolhida","proficiency":"pode adicionar o nível como bônus de proficiência nesses testes, mesmo destreinado","dismissal":true},"needs_review":false}'::jsonb),
  ('spell.player_core_2.cancao_espiritual', 'Canção Espiritual', 'Spiritual Song', 'Canción espiritual', 'Magia de 8º ranque, divina ou ocultista: emite um cone de energia espiritual, causando 14d6 e aplicando efeitos de Fortitude, reações e atordoamento.', '8th-rank divine or occult spell: emits a cone of spiritual energy, dealing 14d6 and applying Fortitude, reaction, and stunned effects.', 'Conjuro divino u ocultista de rango 8: emite un cono de energía espiritual, causa 14d6 y aplica efectos de Fortaleza, reacciones y aturdido.', 8, FALSE, FALSE, ARRAY['divine', 'occult']::text[], 2, NULL, NULL, NULL, 'Fortitude', ARRAY['Concentração', 'Espírito', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 241, '{"heightened":null,"mechanics":{"damage":"14d6 espiritual","criticalSuccess":"sem dano","success":"metade do dano e não pode usar reações até o início do turno","failure":"dano total, sem reações até o início do turno e atordoado 1","criticalFailure":"dano dobrado, sem reações até o início do turno e atordoado 2","incorporeal":"atinge criaturas incorpóreas escondidas em objetos sólidos sem atravessar barreiras","heightened":"+2d6 por ranque"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.ataque_animado', 'Ataque Animado', 'Animated Assault', 'Asalto animado', 'Magia de 2º ranque, arcana ou ocultista: anima objetos desapossados em uma explosão de 3 metros, causando 2d10 de dano contundente e dano menor ao Sustentar.', '2nd-rank arcane or occult spell: animates unattended objects in a 3-meter burst, dealing 2d10 bludgeoning damage and lower damage when Sustained.', 'Conjuro arcano u ocultista de rango 2: anima objetos desatendidos en una explosión de 3 metros, causa 2d10 de daño contundente y daño menor al Mantenerlo.', 2, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 2, '36 metros', NULL, 'sustentada até 1 minuto', 'Reflexos básico', ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 241, '{"heightened":null,"mechanics":{"initialDamage":"2d10 contundente","sustainedDamage":"1d10 contundente na primeira vez que Sustentar a cada rodada","heightened":"+2d10 no dano inicial e +1d10 no dano subsequente por +2 ranques"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.cascata_sagrada', 'Cascata Sagrada', 'Sacred Cascade', 'Cascada sagrada', 'Explode um frasco de água benta em uma explosão de 6 metros, causando 3d6 contundente e 6d6 espiritual adicional a criaturas profanas.', 'Amplifies holy water into a 6-meter burst for 3d6 bludgeoning damage plus 6d6 spirit damage to creatures with the unholy trait.', 'Amplifica agua bendita en una explosión de 6 metros que causa 3d6 contundente y 6d6 espiritual adicional a criaturas profanas.', 4, FALSE, FALSE, ARRAY['divine']::text[], 'two-actions', '150 metros', NULL, NULL, 'Reflexos básico', ARRAY['Água', 'Concentração', 'Manuseio', 'Sagrado']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 241, '{"heightened":null,"mechanics":{"cost":"um frasco de água benta","area":"explosão de 6 metros","damage":"3d6 contundente","profaneDamage":"6d6 espiritual","heightened":"+1: contundente +1d6 e espiritual +2d6","save":"Reflexos básico"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.confinamento', 'Confinamento', 'Detainment', 'Confinamiento', 'Magia de 4º ranque, arcana ou ocultista: envolve uma criatura em um campo de força imóvel com Dureza 10 e 40 PV, bloqueando ataques e passagem.', '4th-rank arcane or occult spell: encloses a creature in an immobile force field with Hardness 10 and 40 HP that blocks attacks and passage.', 'Conjuro arcano u ocultista de rango 4: encierra a una criatura en un campo de fuerza inmóvil con Dureza 10 y 40 PG que bloquea ataques y paso.', 4, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult']::text[], 2, '9 metros', '1 criatura', '1 minuto', 'Reflexos', ARRAY['Concentração', 'Força', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 242, '{"heightened":null,"mechanics":{"field":{"hardness":10,"hp":40,"immunities":["acertos críticos","dano de precisão"],"blocks":"ataques, efeitos e criaturas que tentem atravessar"},"criticalSuccess":"alvo escapa antes da formação","success":"campo se forma parcialmente com 10 PV","failure":"campo funciona normalmente","heightened":"+5 PV no sucesso e +15 PV na falha por ranque"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.cobertor_de_estrelas', 'Cobertor de Estrelas', 'Blanket of Stars', 'Manta de estrellas', 'Magia de 6º ranque: envolve você em escuridão estrelada, concede +2 em Furtividade e, sob céu estrelado, oferece invisibilidade imóvel ou ocultação em movimento.', '6th-rank spell: surrounds you with starry darkness, grants +2 to Stealth, and under a starry sky provides invisibility while still or concealment while moving.', 'Conjuro de rango 6: te envuelve en oscuridad estrellada, concede +2 a Sigilo y bajo un cielo estrellado da invisibilidad al estar quieto u ocultación al moverte.', 6, FALSE, FALSE, ARRAY['occult', 'primal']::text[], 2, NULL, NULL, '10 minutos', 'Vontade', ARRAY['Concentração', 'Ilusão', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 242, '{"heightened":null,"mechanics":{"stealth":"+2 de bônus de estado em testes de Furtividade para Esconder e Esgueirar","starlitSky":"ao ar livre sob céu estrelado, fica invisível enquanto imóvel e ocultado enquanto se move","adjacentTrigger":"criatura que termina o turno adjacente faz salvamento de Vontade; efeito mental e visual","success":"não afetada","failure":"ofuscada até o fim do próximo turno","criticalFailure":"confusa e ofuscada até o fim do próximo turno"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.conselho_onirico', 'Conselho Onírico', 'Dream Council', 'Consejo onírico', 'Magia de 8º ranque, arcana ou ocultista: reúne até 12 criaturas em um sonho compartilhado por 1 hora, desde que escolham dormir.', '8th-rank arcane or occult spell: brings up to 12 creatures into a shared dream for 1 hour if they choose to sleep.', 'Conjuro arcano u ocultista de rango 8: reúne hasta 12 criaturas en un sueño compartido durante 1 hora si eligen dormir.', 8, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 'two-actions', 'planetário', 'até 12 criaturas conhecidas pelo nome e encontradas pessoalmente', '1 hora', NULL, ARRAY['Concentração', 'Ilusão', 'Manuseio', 'Mental', 'Sono']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 242, '{"heightened":null,"mechanics":{"sharedDream":"alvos que escolhem dormir entram em um sonho compartilhado e se comunicam como se estivessem na mesma sala","awake":"cada alvo sai ao despertar; a magia termina quando todos acordam","refusal":"a magia termina para qualquer alvo que escolha não dormir"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.cofre_imaginario', 'Cofre Imaginário', 'Imaginary Vault', 'Bóveda imaginaria', 'Magia de 5º ranque: armazena mentalmente um recipiente e seu conteúdo de até Volume 10 até a próxima preparação diária, permitindo retirar itens com uma atividade de 3 ações.', '5th-rank spell: stores a container and up to Bulk 10 of contents in your mind until your next daily preparations, allowing items to be retrieved with a 3-action activity.', 'Conjuro de rango 5: almacena en tu mente un recipiente y hasta Volumen 10 de contenido hasta tus próximas preparaciones diarias, permitiendo retirar objetos con una actividad de 3 acciones.', 5, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 1, 'toque', '1 recipiente e seu conteúdo, com até Volume 10 no total', 'até a próxima preparação diária', NULL, ARRAY['Concentração', 'Manuseio', 'Mental']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 242, '{"heightened":null,"mechanics":{"storage":"transforma recipiente e conteúdo em forma imaginária armazenada na mente do conjurador","restriction":"não pode conter criaturas","retrieval":"retirar um item exige atividade de 3 ações com traços concentração e manuseio","noReturn":"itens retirados não podem ser colocados de volta","ending":"pode ser dispensada; ao terminar, o recipiente reaparece nas mãos ou no chão próximo"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.convocar_servo_menor', 'Convocar Servo Menor', 'Summon Lesser Servitor', 'Convocar sirviente menor', 'Magia divina de 1º ranque: convoca por até 1 minuto um habitante de nível -1 da Esfera Externa, respeitando a santificação da sua divindade.', '1st-rank divine spell: summons a level -1 inhabitant of the Outer Sphere for up to 1 minute, respecting your deity''s sanctification.', 'Conjuro divino de rango 1: convoca durante hasta 1 minuto a un habitante de nivel -1 de la Esfera Exterior, respetando la santificación de tu divinidad.', 1, FALSE, FALSE, ARRAY['divine']::text[], 3, '9 metros', NULL, 'sustentada até 1 minuto', NULL, ARRAY['Concentração', 'Conjuração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 242, '{"heightened":null,"mechanics":{"creature":"celestial, ínfero ou monitor de nível -1; também pode ser animal da Esfera Externa de nível -1","sanctification":"o servidor sagrado ou profano precisa ser permitido pela santificação da divindade","anathema":"convocar traço sagrado ou profano proibido pela divindade","choices":["celeste e sagrado","ínfero e profano","monitor"]},"needs_review":false}'::jsonb),
  ('spell.player_core_2.cone_gelido', 'Cone Gélido', 'Chilling Cone', 'Cono gélido', 'Magia de 1º ranque, arcana ou primal: lança fragmentos de gelo em um cone de 4,5 metros, causando 2d4 de frio e reduzindo Velocidades na falha.', '1st-rank arcane or primal spell: blasts a 4.5-meter cone of ice for 2d4 cold damage and reduces Speed on a failure.', 'Conjuro arcano o primigenio de rango 1: lanza hielo en un cono de 4,5 metros, causa 2d4 de frío y reduce Velocidades si se falla.', 1, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 2, NULL, NULL, NULL, 'Reflexos', ARRAY['Concentração', 'Frio', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 242, '{"heightened":null,"mechanics":{"damage":"2d4 frio","criticalSuccess":"não afetado","success":"metade do dano","failure":"dano total e -1,5 metro nas Velocidades por 2 rodadas"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.crescimentos_macabros', 'Crescimentos Macabros', 'Macabre Growths', 'Crecimientos macabros', 'Magia de 5º ranque, arcana ou primal: faz uma criatura corpórea desenvolver crescimentos, causando 10d6 perfurante e podendo deixar criaturas próximas enjoada.', '5th-rank arcane or primal spell: causes a corporeal creature to develop grotesque growths, dealing 10d6 piercing damage and potentially sickening nearby creatures.', 'Conjuro arcano o primigenio de rango 5: hace que una criatura corpórea desarrolle crecimientos grotescos, causa 10d6 perforante y puede provocar nauseado a criaturas cercanas.', 5, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 2, '18 metros', '1 criatura corpórea', NULL, 'Fortitude básico e Vontade', ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 243, '{"heightened":null,"mechanics":{"primaryDamage":"10d6 perfurante; partes extras apodrecem após 1 rodada","immunity":"não afeta anatomia mutável ou criaturas sem membros","secondaryArea":"criaturas a até 9 metros fazem salvamento de Vontade, efeito mental e visual; imunidade por 1 hora","success":"não afetado","failure":"enjoado 1","criticalFailure":"enjoado 2","heightened":"+2d6 no dano por ranque"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.cores_desconcertantes', 'Cores Desconcertantes', 'Dazzling Colors', 'Colores desconcertantes', 'Magia de 8º ranque, arcana ou ocultista: cria uma nuvem de cores que ofusca e força salvamentos de Vontade, podendo deixar criaturas confusas ou atordoadas.', '8th-rank arcane or occult spell: creates a cloud of colors that dazzles and forces Will saves, potentially confusing or stunning creatures.', 'Conjuro arcano u ocultista de rango 8: crea una nube de colores que deslumbra y exige salvaciones de Voluntad, pudiendo confundir o aturdir criaturas.', 8, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 2, '36 metros', NULL, 'sustentada até 1 minuto', 'Vontade', ARRAY['Ilusão', 'Incapacitação', 'Manuseio', 'Sutil', 'Visual']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 243, '{"heightened":null,"mechanics":{"obscured":"criaturas na nuvem e a até 6 metros ficam ofuscadas","trigger":"salvamento ao conjurar dentro da nuvem, entrar, terminar turno nela ou Buscar/Interagir na nuvem","success":"não afetado","failure":"confuso por 1d4 rodadas","criticalFailure":"atordoado por 1d4 rodadas e depois confuso pelo restante da duração"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.dama_vampirica', 'Dama Vampírica', 'Vampiric Maiden', 'Dama vampírica', 'Magia de 4º ranque, arcana, divina ou ocultista: uma dama de ferro drena 4d4 perfurante e 4d4 eversivo, concedendo PV temporários ao conjurador.', '4th-rank arcane, divine, or occult spell: a vampiric iron maiden deals 4d4 piercing and 4d4 void damage and grants the caster temporary HP.', 'Conjuro arcano, divino u ocultista de rango 4: una dama de hierro vampírica causa 4d4 perforante y 4d4 de vacío y concede PG temporales al lanzador.', 4, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult']::text[], 2, '9 metros', '1 criatura', NULL, 'Fortitude', ARRAY['Concentração', 'Eversão', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 243, '{"heightened":null,"mechanics":{"damage":"4d4 perfurante + 4d4 eversivo","temporaryHp":"ganha PV temporários iguais ao dano eversivo sofrido pelo alvo; duram 1 minuto","criticalSuccess":"não afetado","success":"metade do dano","failure":"dano total e imobilizado por 1 rodada ou até Interagir para se libertar","criticalFailure":"dano dobrado e imobilizado por 1 rodada ou até Escapar contra sua CD de magia","heightened":"+1d4 em cada tipo de dano por ranque"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.deja_vu', 'Déjà Vu', 'Déjà Vu', 'Déjà vu', 'Força uma criatura a repetir, na mesma ordem, as ações do próximo turno; ações impossíveis podem ser escolhidas livremente, mas deixam o alvo atordoado 1.', 'Forces a creature to repeat the next turn''s actions in the same order; impossible actions can be chosen freely but leave the target stunned 1.', 'Obliga a una criatura a repetir en el mismo orden las acciones de su próximo turno; las imposibles pueden elegirse libremente, pero dejan al objetivo aturdido 1.', 1, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 'two-actions', '30 metros', '1 criatura', '2 rodadas', 'Vontade', ARRAY['Concentração', 'Incapacitação', 'Manuseio', 'Mental']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 243, '{"heightened":null,"mechanics":{"duration":"2 rodadas","save":"Vontade","failure":"repete as ações do próximo turno","impossibleAction":"pode agir livremente e fica atordoado 1"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.desmontar', 'Desmontar', 'Disassemble', 'Desmontar', 'Magia de 2º ranque, arcana ou primal: desmonta um objeto mundano leve em peças escondíveis e o recompõe ao fim da duração.', '2nd-rank arcane or primal spell: disassembles a light mundane object into concealable pieces and reassembles it when the duration ends.', 'Conjuro arcano o primigenio de rango 2: desmonta un objeto mundano ligero en piezas ocultables y lo recompone al terminar la duración.', 2, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 2, 'toque', '1 objeto mundano de Volume leve ou menos em sua posse', '1 minuto', NULL, ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 244, '{"heightened":null,"mechanics":{"effect":"objeto se desmonta em peças, recebe quebrado e suas peças ficam pequenas para esconder","limitation":"falha sem peças; usar em objeto perigoso normalmente o aciona","restore":"ao terminar, recompõe-se, perde quebrado e recupera os PV anteriores","heightened":{"rank4":"10 minutos","rank6":"até as próximas preparações diárias"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.despertar_esqueletos', 'Despertar Esqueletos', 'Awaken Skeletons', 'Despertar esqueletos', 'Magia de 3º ranque, arcana, divina ou ocultista: cria uma área de esqueletos em terreno difícil que causa 2d6 cortante ao surgir e ao ser movida.', '3rd-rank arcane, divine, or occult spell: creates a difficult-terrain skeleton area that deals 2d6 slashing damage when it appears and moves.', 'Conjuro arcano, divino u ocultista de rango 3: crea un área de esqueletos con terreno difícil que causa 2d6 cortante al aparecer y moverse.', 3, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult']::text[], 2, '18 metros', NULL, 'sustentada até 1 minuto', 'Reflexos básico', ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 244, '{"heightened":null,"mechanics":{"terrain":"a área ocupada pelos esqueletos é terreno difícil","damage":"2d6 cortante ao surgir e ao mover a área","sustain":"move a área até 6 metros na distância da magia uma vez por rodada","replacement":"ossos se recompõem e substituem os destruídos","heightened":"+1d6 por +2 ranques"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.drenar_cores', 'Drenar Cores', 'Drain Color', 'Drenar colores', 'Magia ocultista de 4º ranque: drena cor e vitalidade de uma criatura viva; o salvamento de Fortitude determina enfraquecido e drenado, com penalidade adicional contra gnomos.', '4th-rank occult spell: drains color and vitality from a living creature; its Fortitude save determines clumsy and drained conditions, with an additional penalty for gnomes.', 'Conjuro ocultista de rango 4: drena el color y la vitalidad de una criatura viva; su salvación de Fortaleza determina las condiciones debilitado y drenado, con una penalización adicional contra gnomos.', 4, FALSE, FALSE, ARRAY['occult']::text[], 2, 'toque', '1 criatura viva', NULL, 'Fortitude', ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 244, '{"heightened":null,"mechanics":{"gnomePenalty":"criaturas com o traço gnomo sofrem –2 de penalidade de circunstância no salvamento","success":"enfraquecido 2 por 1 rodada","failure":"enfraquecido 2 por 1 minuto, drenado 1 e apatia; por 1 rodada, ação de movimento exige salvamento de Vontade ou é perdida","criticalFailure":"enfraquecido 2 e drenado 2 permanentemente, removíveis por efeitos apropriados"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.embotar_ambicao', 'Embotar Ambição', 'Dull Ambition', 'Embotar ambición', 'Magia de 4º ranque, arcana, divina ou ocultista: amaldiçoa a ambição do alvo, impondo infortúnio em iniciativa e atividades de recesso.', '4th-rank arcane, divine, or occult spell: curses a target''s ambition, imposing misfortune on initiative and downtime activity checks.', 'Conjuro arcano, divino u ocultista de rango 4: maldice la ambición del objetivo e impone infortunio en iniciativa y actividades de descanso.', 4, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult']::text[], 2, '36 metros', '1 criatura', 'varia', 'Vontade', ARRAY['Concentração', 'Infortúnio', 'Maldição', 'Manuseio', 'Mental']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 244, '{"heightened":null,"mechanics":{"criticalSuccess":"não afetado","success":"por 1 hora, rola duas vezes iniciativa e usa o pior resultado","failure":"por 1 dia, rola duas vezes iniciativa e testes de recesso e usa o pior resultado","criticalFailure":"como falha, com duração ilimitada"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.encolher_item', 'Encolher Item', 'Shrink Item', 'Encoger objeto', 'Magia arcana de 3º ranque: reduz um objeto mundano grande a quase o tamanho de uma moeda até as próximas preparações diárias.', '3rd-rank arcane spell: shrinks a mundane object to about coin size until your next daily preparations.', 'Conjuro arcano de rango 3: reduce un objeto mundano a aproximadamente el tamaño de una moneda hasta tus próximas preparaciones diarias.', 3, FALSE, FALSE, ARRAY['arcane']::text[], 'two-actions', 'toque', '1 objeto mundano de até 0,6 metros cúbicos e até 80 Volumes', 'até as próximas preparações diárias', NULL, ARRAY['Concentração', 'Manuseio', 'Morfia']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 244, '{"heightened":null,"mechanics":{"size":"tamanho aproximado de uma moeda, Volume insignificante","termination":"termina ao Dispensar ou lançar o objeto em superfície sólida","limitation":"objeto não pode atacar ou causar dano enquanto retorna ao tamanho normal","space":"se não houver espaço, duração continua até existir espaço suficiente"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.epidemia_espiritual', 'Epidemia Espiritual', 'Spiritual Epidemic', 'Epidemia espiritual', 'Magia de 8º ranque, divina ou ocultista: espalha uma maldição espiritual contagiosa que repete ações e aplica enfraquecido e estupefato conforme o salvamento de Vontade.', '8th-rank divine or occult spell: spreads a contagious spiritual curse that repeats actions and applies enfeebled and stupefied based on the Will save.', 'Conjuro divino u ocultista de rango 8: propaga una maldición espiritual contagiosa que repite acciones y aplica debilitado y atontado según la salvación de Voluntad.', 8, FALSE, FALSE, ARRAY['divine', 'occult']::text[], 2, '36 metros', '1 criatura', 'varia', 'Vontade', ARRAY['Concentração', 'Espírito', 'Maldição', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 244, '{"heightened":null,"mechanics":{"contagion":"criaturas que conjuram magia divina ou ocultista no alvo também fazem salvamento de Vontade","failureEffect":"ações do próximo turno devem ser repetidas no turno seguinte na mesma ordem; ação impossível permite agir livremente, mas deixa atordoado 1 até o fim do turno","criticalSuccess":"não afetado","success":"enfraquecido 2 e estupefato 2 por 1 rodada","failure":"enfraquecido 2 e estupefato 2 por 1 minuto, depois enfraquecido 1 e estupefato 1 permanentemente","criticalFailure":"enfraquecido 3 e estupefato 3 por 1 minuto, depois enfraquecido 2 e estupefato 2 permanentemente"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.esmorecimento_subito', 'Esmorecimento Súbito', 'Sudden Blight', 'Decaimiento repentino', 'Magia de 2º ranque, divina ou primal: acelera a decomposição em uma explosão de 6 metros, causando 2d10 eversivo e apodrecendo plantas mundanas.', '2nd-rank divine or primal spell: accelerates decay in a 6-meter burst, dealing 2d10 void damage and rotting mundane plants.', 'Conjuro divino o primigenio de rango 2: acelera la descomposición en una explosión de 6 metros, causa 2d10 de vacío y pudre plantas mundanas.', 2, FALSE, FALSE, ARRAY['divine', 'primal']::text[], 2, '36 metros', NULL, NULL, 'Fortitude básico', ARRAY['Concentração', 'Eversão', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 245, '{"heightened":null,"mechanics":{"damage":"2d10 eversivo a cada criatura viva","diseasePenalty":"criaturas afetadas por doença sofrem -2 circunstancial no salvamento","plants":"apodrece plantas Pequenas e Minúsculas não criaturas, removendo vegetação, terreno difícil, cobertura e ocultamento mundanos","dispel":"tenta neutralizar efeitos mágicos nas plantas","heightened":"+1d10 por ranque"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.exigencia_telepatica', 'Exigência Telepática', 'Telepathic Demand', 'Exigencia telepática', 'Magia de 9º ranque, arcana, divina ou ocultista: envia uma exigência telepática planetária com efeito de sugestão a uma criatura já contatada.', '9th-rank arcane, divine, or occult spell: sends a planetary telepathic demand with the effect of suggestion to a creature previously contacted.', 'Conjuro arcano, divino u ocultista de rango 9: envía una exigencia telepática planetaria con efecto de sugerencia a una criatura contactada antes.', 9, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 3, 'planetário', '1 criatura com a qual você já teve contato telepático', 'varia', 'Vontade', ARRAY['Concentração', 'Incapacitação', 'Linguístico', 'Manuseio', 'Mental']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 245, '{"heightened":null,"mechanics":{"message":"envia até 25 palavras; alvo pode responder imediatamente com até 25 palavras","effect":"mensagem ardilosa produz efeito de sugestão","successImmunity":"imunidade temporária por 1 dia","criticalSuccessImmunity":"imunidade temporária por 1 mês","requirement":"contato telepático anterior"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.fingir_de_morto', 'Fingir de Morto', 'Feign Death', 'Fingir la muerte', 'Magia incomum de 5º ranque: como reação, faz uma criatura parecer morta e ficar invisível enquanto deixa um cadáver ilusório no local.', 'Uncommon 5th-rank spell: as a reaction, makes a creature appear dead and become invisible while leaving an illusory corpse behind.', 'Conjuro poco común de rango 5: como reacción, hace que una criatura parezca muerta y quede invisible mientras deja un cadáver ilusorio.', 5, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult']::text[], 'two-actions', '36 metros', '1 criatura', 'sustentada até 1 minuto', NULL, ARRAY['Incomum', 'Ilusão', 'Manuseio', 'Sutil', 'Visual']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 245, '{"heightened":null,"mechanics":{"effect":"alvo parece morto e fica invisível; cadáver ilusório permanece no local","hostileActions":"magia termina se alvo realizar ações hostis e o cadáver desaparece","disbelief":"Mestre pode permitir Percepção para desacreditar uma morte absurda","heightened":"no 7º ranque não termina quando o alvo realiza ações hostis"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.forma_sagrada', 'Forma Sagrada', 'Holy Form', 'Forma sagrada', 'Magia divina de 6º ranque: transforma o conjurador em uma forma de batalha com CA 20 + nível, 10 PV temporários, resistência física e armamento sagrado.', '6th-rank divine spell: transforms the caster into a battle form with AC 20 + level, 10 temporary HP, physical resistance, and a sacred armament.', 'Conjuro divino de rango 6: transforma al lanzador en una forma de batalla con CA 20 + nivel, 10 PG temporales, resistencia física y armamento sagrado.', 6, FALSE, FALSE, ARRAY['divine']::text[], 2, NULL, NULL, '1 minuto', NULL, ARRAY['Concentração', 'Manuseio', 'Morfia']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 245, '{"heightened":null,"mechanics":{"ac":"20 + nível","temporaryHp":10,"speed":"12 metros","physicalResistance":3,"senses":["visão no escuro"],"weapon":{"attack":"+21","damageBonus":"+8 ou +6 à distância","damage":"3d6 contundente + 1d6 espiritual","favoredDeityWeapon":true},"athletics":"+23","restrictions":"apenas o armamento sagrado pode ser usado; forma mantém tamanho e aparência semelhante"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.fosso_de_lama', 'Fosso de Lama', 'Mud Pit', 'Foso de lodo', 'Magia de 1º ranque, arcana ou primal: cobre o chão em uma explosão de 4,5 metros com lama pegajosa que é terreno difícil.', '1st-rank arcane or primal spell: covers a 4.5-meter burst of ground with sticky mud that is difficult terrain.', 'Conjuro arcano o primigenio de rango 1: cubre una explosión de 4,5 metros del suelo con barro pegajoso que es terreno difícil.', 1, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 3, '18 metros', NULL, '1 minuto', NULL, ARRAY['Água', 'Concentração', 'Manuseio', 'Terra']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 246, '{"heightened":null,"mechanics":{"terrain":"lama com 30 centímetros de profundidade torna a área terreno difícil"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.furor_cegante', 'Furor Cegante', 'Blinding Fury', 'Furia cegadora', 'Magia de 6º ranque, divina, ocultista ou primal: como reação ao sofrer dano, amaldiçoa o agressor para que não consiga observar você.', '6th-rank divine, occult, or primal spell: as a reaction when damaged, curses the attacker so it cannot observe you.', 'Conjuro divino, ocultista o primigenio de rango 6: como reacción al recibir daño, maldice al atacante para que no pueda observarte.', 6, FALSE, FALSE, ARRAY['divine', 'occult', 'primal']::text[], 'two-actions', '18 metros', 'a criatura acionadora', 'varia', 'Vontade', ARRAY['Concentração', 'Emoção', 'Incapacitação', 'Maldição', 'Mental']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 246, '{"heightened":null,"mechanics":{"trigger":"uma criatura causa dano a você","criticalSuccess":"não afetado","success":"alvo não pode observar você até o fim do turno; se observava, você fica escondido","failure":"como sucesso; por 1 minuto, quando alvo causar dano a você, não pode observá-lo até o fim do turno","criticalFailure":"como sucesso; duração ilimitada e, na primeira vez por rodada que causar dano, não pode observar a criatura atingida"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.geometria_estranha', 'Geometria Estranha', 'Strange Geometry', 'Geometría extraña', 'Magia ocultista de 5º ranque: distorce quatro cubos separados em geometria ilusória, tornando o terreno difícil e teleportando criaturas para saídas aleatórias.', '5th-rank occult spell: distorts four separated cubes into illusory geometry, making terrain difficult and teleporting creatures to random exits.', 'Conjuro ocultista de rango 5: distorsiona cuatro cubos separados en geometría ilusoria, vuelve difícil el terreno y teletransporta criaturas a salidas aleatorias.', 5, FALSE, FALSE, ARRAY['occult']::text[], 3, '9 metros', NULL, '1 minuto', 'Vontade', ARRAY['Concentração', 'Ilusão', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 246, '{"heightened":null,"mechanics":{"success":"desacredita a ilusão","failure":"cubos são terreno difícil, inclusive ar e paredes; ao sair, teleporta para cubo aleatório compatível","interaction":"interagir com a ilusão permite novo salvamento para desacreditá-la","teleportation":"criatura escolhe a extremidade do cubo de saída; Mestre exclui cubos sem terreno compatível"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.gravar_mensagem', 'Gravar Mensagem', 'Record Message', 'Grabar mensaje', 'Magia ocultista de 1º ranque: grava uma mensagem ou emoção em um objeto, revelada por Ler Objeto e detectável por Ler Aura superior.', '1st-rank occult spell: records a message or emotion in an object, revealed by Read Object and detectable by a higher-rank Read Aura.', 'Conjuro ocultista de rango 1: graba un mensaje o emoción en un objeto, revelado por Leer objeto y detectable por Leer aura de rango superior.', 1, FALSE, FALSE, ARRAY['occult']::text[], 2, 'toque', '1 objeto', NULL, NULL, ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 246, '{"heightened":null,"mechanics":{"recording":"grava mensagem curta ou tema emocional escolhido","readObject":"é revelada por Ler Objeto e substitui eventos emotivos anteriores","retrocognition":"aparece como evento importante na linha do tempo sem interferir em outras visões","detectMagic":"Ler Aura de ranque superior percebe a alteração mágica","overwrite":"conjurar novamente remove vibração anterior"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.impulso_caridoso', 'Impulso Caridoso', 'Charitable Urge', 'Impulso caritativo', 'Magia de 2º ranque, arcana, divina ou ocultista: concede uma forma de batalha com armamento sagrado, CA 20 + nível, 10 PV temporários e resistência física.', '2nd-rank arcane, divine, or occult spell: grants a battle form with a sacred armament, AC 20 + level, 10 temporary HP, and physical resistance.', 'Conjuro arcano, divino u ocultista de rango 2: concede una forma de batalla con armamento sagrado, CA 20 + nivel, 10 PG temporales y resistencia física.', 2, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult']::text[], 2, '9 metros', '1 criatura', NULL, NULL, ARRAY['Concentração', 'Incapacitação', 'Manuseio', 'Mental']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 246, '{"heightened":null,"mechanics":{"battleForm":true,"ac":"20 + nível","temporaryHp":10,"speed":"12 metros","physicalResistance":3,"senses":["visão no escuro"],"weapon":{"attack":"+21","damageBonus":"+8 ou +6 à distância","damage":"3d6 contundente + 1d6 espiritual","onlyAttack":true},"athletics":"+23","heightened":"8º ranque: CA 21 + nível, 15 PV temporários, resistência 4, ataque +28, dano +15 ou +12 à distância, Atletismo +29 e tamanho Grande"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.insultos_abrasadores', 'Insultos Abrasadores', 'Scorching Insults', 'Insultos abrasadores', 'Magia ocultista de 2º ranque: insultos ardentes causam 2d6 de fogo persistente e deixam o alvo assustado conforme o salvamento de Vontade.', '2nd-rank occult spell: burning insults deal 2d6 persistent fire damage and frighten the target based on its Will save.', 'Conjuro ocultista de rango 2: insultos abrasadores causan 2d6 de fuego persistente y asustan al objetivo según su salvación de Voluntad.', 2, FALSE, FALSE, ARRAY['occult']::text[], 2, '9 metros', '1 criatura', NULL, 'Vontade', ARRAY['Auditivo', 'Concentração', 'Emoção', 'Manuseio', 'Medo', 'Mental']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 247, '{"heightened":null,"mechanics":{"damage":"2d6 fogo persistente","languageBonus":"alvo que não entende o idioma ou não ouve recebe +4 circunstancial no salvamento","criticalSuccess":"não afetado","success":"metade do dano persistente","failure":"assustado 1 e dano persistente total","criticalFailure":"assustado 2 e dobro do dano persistente","heightened":"+2 ranques: até duas criaturas adicionais e +2d6 de dano"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.infestacao_fungica', 'Infestação Fúngica', 'Fungal Infestation', 'Infestación fúngica', 'Magia primal de 2º ranque: espalha esporos em um cone, causando dano persistente de veneno e fraquezas a fogo e cortante conforme o salvamento de Fortitude.', '2nd-rank primal spell: spreads spores in a cone, dealing persistent poison damage and imposing fire and slashing weaknesses based on the Fortitude save.', 'Conjuro primigenio de rango 2: esparce esporas en un cono, causando daño persistente de veneno e imponiendo debilidades a fuego y cortante según la salvación de Fortaleza.', 2, FALSE, FALSE, ARRAY['primal']::text[], 2, 'toque', NULL, NULL, 'Fortitude', ARRAY['Concentração', 'Fungo', 'Manuseio', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 247, '{"heightened":null,"mechanics":{"damage":"2d6 de dano persistente de veneno","success":"metade do dano persistente de veneno","failure":"dano persistente total e fraqueza 1 a fogo e cortante enquanto sofrer o dano","criticalFailure":"dobro do dano persistente e fraqueza 2 a fogo e cortante enquanto sofrer o dano","heightened":{"rank4":"dano persistente aumenta em 2d6 e fraquezas em 1, ou em 2 na falha crítica"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.inimizade_da_natureza', 'Inimizade da Natureza', 'Nature''s Enmity', 'Enemistad de la naturaleza', 'Magia primal de 9º ranque: volta animais, plantas e fungos contra até cinco criaturas em uma área de 150 metros, com penalidade de movimento, ataques aleatórios e bloqueio de magias primais.', '9th-rank primal spell: turns animals, plants, and fungi against up to five creatures in a 150-meter burst, imposing movement penalties, random attacks, and primal spell disruption.', 'Conjuro primigenio de rango 9: vuelve animales, plantas y hongos contra hasta cinco criaturas en una explosión de 150 metros, con penalizaciones de movimiento, ataques aleatorios e interrupción de conjuros primigenios.', 9, FALSE, FALSE, ARRAY['primal']::text[], 2, '36 metros', 'até 5 criaturas', '10 minutos', NULL, ARRAY['Concentração', 'Madeira', 'Manuseio', 'Planta']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 247, '{"heightened":null,"mechanics":{"movement":"vegetação impõe –3 metros de penalidade de circunstância na Velocidade quando adjacente a plantas e fungos","animalAttack":"no início do turno, teste simples CD 8; falha provoca 2d10 cortante, salvamento básico de Reflexos e desprevenido por 1 rodada salvo sucesso crítico","primalMagic":"teste simples CD 5 ao conjurar magia primal; falha faz a magia falhar","hostility":"animais, fungos e plantas ficam hostis ao alvo","exception":"o Mestre pode excluir criaturas que não possam ser afetadas pela ira da natureza"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.invisibilidade_compartilhada', 'Invisibilidade Compartilhada', 'Shared Invisibility', 'Invisibilidad compartida', 'Magia de 3º ranque, arcana ou ocultista: torna você e até cinco criaturas voluntárias invisíveis dentro de uma emanação de 9 metros.', '3rd-rank arcane or occult spell: makes you and up to five willing creatures invisible within a 9-meter emanation.', 'Conjuro arcano u ocultista de rango 3: vuelve invisibles a ti y hasta cinco criaturas voluntarias dentro de una emanación de 9 metros.', 3, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 2, NULL, 'você e até 5 criaturas voluntárias', '10 minutos', NULL, ARRAY['Aura', 'Ilusão', 'Manuseio', 'Sutil']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 247, '{"heightened":null,"mechanics":{"effect":"alvos ficam invisíveis entre si enquanto permanecem na emanação","leaving":"criatura que sai fica visível e não recupera invisibilidade ao voltar","hostileAction":"magia termina após ação hostil de criatura tornada invisível","heightened":"5º ranque: até 10 criaturas voluntárias e duração de 1 hora"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.item_invisivel', 'Item Invisível', 'Invisible Item', 'Objeto invisible', 'Magia de 1º ranque, arcana ou ocultista: torna um objeto invisível e indetectado por 1 hora, com regras específicas para armas e munições.', '1st-rank arcane or occult spell: makes an object invisible and undetected for 1 hour, with special rules for weapons and ammunition.', 'Conjuro arcano u ocultista de rango 1: vuelve invisible e indetectable un objeto durante 1 hora, con reglas especiales para armas y munición.', 1, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 2, 'toque', '1 objeto', '1 hora', NULL, ARRAY['Concentração', 'Ilusão', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 247, '{"heightened":null,"mechanics":{"effect":"objeto fica invisível e indetectado, mas pode ser encontrado e fica escondido após sucesso","hostileUse":"termina depois da ação hostil que usa o objeto","weapon":"arma invisível normalmente não concede vantagem; arma arremessada ou munição pode ocultar a posição do atacante até retornar"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.jaula_verdejante', 'Jaula Verdejante', 'Verdant Cage', 'Jaula verdosa', 'Magia arcana ou primal de 7º ranque: cria uma jaula invisível de madeira vitalizada com CA 10, Dureza 20 e 40 PV, prendendo criaturas conforme Reflexos.', '7th-rank arcane or primal spell: creates an invisible vitalized-wood cage with AC 10, Hardness 20, and 40 HP that traps creatures based on Reflex saves.', 'Conjuro arcano o primigenio de rango 7: crea una jaula invisible de madera vitalizada con CA 10, Dureza 20 y 40 PG que atrapa criaturas según sus salvaciones de Reflejos.', 7, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 3, '9 metros', NULL, 'sustentada até 1 minuto', 'Reflexos', ARRAY['Concentração', 'Madeira', 'Manuseio', 'Vitalidade']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 248, '{"heightened":null,"mechanics":{"cage":{"ac":10,"hardness":20,"hp":40,"immunity":["acertos críticos","dano de precisão"],"weakness":{"void":5},"cover":"cobertura padrão"},"criticalSize":"falha se criatura for grande demais para caber","success":"criatura é empurrada para fora em espaço escolhido","failure":"criatura fica presa dentro","escape":"criaturas capazes de passar entre as barras podem sair; mortos-vivos incorpóreos não atravessam","effects":"magias e a maioria dos efeitos de área atravessam sem impedimentos"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.lodo_corrosivo', 'Lodo Corrosivo', 'Corrosive Mud', 'Lodo corrosivo', 'Cria duas poças de lodo que são terreno difícil maior; criaturas que começam ou entram nelas sofrem 8d6 de ácido, com 1d6 persistente adicional em falha crítica.', 'Creates two pools of corrosive mud that are greater difficult terrain; creatures starting or entering them take 8d6 acid damage, plus 1d6 persistent acid on a critical failure.', 'Crea dos charcos de barro corrosivo que son terreno difícil mayor; las criaturas que empiezan o entran sufren 8d6 de ácido y 1d6 persistente adicional con fallo crítico.', 5, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'two-actions', '36 metros', 'todos os quadrados em duas explosões de 3 metros', '1 minuto', 'Reflexos básico', ARRAY['Ácido', 'Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 248, '{"heightened":null,"mechanics":{"area":"duas explosões de 3 metros","damage":"8d6 ácido","criticalFailure":"1d6 dano persistente de ácido","terrain":"terreno difícil maior","heightened":"+2: uma explosão adicional"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.lanterna_do_ceifador', 'Lanterna do Ceifador', 'Reaper''s Lantern', 'Linterna del segador', 'Magia de 2º ranque, divina, ocultista ou primal: invoca uma lanterna espectral que enfraquece mortos-vivos e reduz cura de vivos após falha de Fortitude.', '2nd-rank divine, occult, or primal spell: summons a spectral lantern that weakens undead and reduces living creatures'' healing after a failed Fortitude save.', 'Conjuro divino, ocultista o primigenio de rango 2: invoca una linterna espectral que debilita no muertos y reduce la curación de vivos tras fallar Fortaleza.', 2, FALSE, FALSE, ARRAY['divine', 'occult', 'primal']::text[], 2, NULL, NULL, '1 minuto', 'Fortitude', ARRAY['Aura', 'Concentração', 'Luz', 'Manuseio', 'Morte']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 248, '{"heightened":null,"mechanics":{"light":"luz forte na área e luz fraca no dobro da área","livingFailure":"criaturas vivas recebem apenas metade do benefício normal de cura na área","undeadFailure":"mortos-vivos ficam enfraquecido 1 na área","repeatedSave":"criatura usa o mesmo resultado ao sair e retornar","sustain":"uma vez por turno a partir da rodada seguinte, aumenta a emanação em 1,5 metro e força novos salvamentos"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.ler_objeto', 'Ler Objeto', 'Read Object', 'Leer objeto', 'Obtém uma impressão psíquica sobre um evento emocional que envolveu o objeto na última semana, conforme determinado pelo Mestre.', 'Learns a psychic impression about an emotional event involving the object during the last week, as determined by the GM.', 'Obtiene una impresión psíquica sobre un evento emocional relacionado con el objeto durante la última semana, según determine el DJ.', 1, FALSE, FALSE, ARRAY['occult']::text[], 'two-actions', 'toque', '1 objeto', NULL, NULL, ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 248, '{"heightened":null,"mechanics":{"range":"toque","target":"1 objeto","lookback":"última semana","heightened":{"2":"último mês","4":"último ano","6":"última década","8":"último século","9":"toda a história do objeto"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.maldicao_bestial', 'Maldição Bestial', 'Bestial Curse', 'Maldición bestial', 'Magia de 4º ranque, arcana, ocultista ou primal: amaldiçoa um humanoide vivo com uma forma bestial e penalidades conforme o salvamento de Fortitude.', '4th-rank arcane, occult, or primal spell: curses a living humanoid with a bestial form and penalties based on its Fortitude save.', 'Conjuro arcano, ocultista o primigenio de rango 4: maldice a un humanoide vivo con una forma bestial y penalizaciones según su salvación de Fortaleza.', 4, FALSE, FALSE, ARRAY['arcane', 'occult', 'primal']::text[], 2, 'toque', '1 humanoide vivo', 'varia', 'Fortitude', ARRAY['Concentração', 'Maldição', 'Manuseio', 'Morfia']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 248, '{"heightened":null,"mechanics":{"criticalSuccess":"não afetado","success":"características bestiais menores e desajejado 1 por 1 rodada","failure":"forma bestial por 1 hora, desajejado 1, fraqueza 1 a prata, ataque de garra/casco/chifre/mandíbula e teste simples CD 5 para ações de manuseio","criticalFailure":"como falha, mas duração ilimitada","heightened":{"rank3":"até as próximas preparações diárias","rank7":"duração ilimitada"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.maldicao_do_tempo_perdido', 'Maldição do Tempo Perdido', 'Curse of Lost Time', 'Maldición del tiempo perdido', 'Magia de 3º ranque: acelera envelhecimento ou desgaste de objetos, constructos e criaturas vivas, causando dano e condições conforme o alvo e o salvamento de Fortitude.', '3rd-rank spell: accelerates aging or wear on objects, constructs, and living creatures, dealing damage and imposing conditions based on the target and Fortitude save.', 'Conjuro de rango 3: acelera el envejecimiento o desgaste de objetos, constructos y criaturas vivas, causando daño y condiciones según el objetivo y la salvación de Fortaleza.', 3, FALSE, FALSE, ARRAY['arcane', 'occult', 'primal']::text[], 2, 'toque', '1 objeto, constructo ou criatura viva Grande ou menor', NULL, 'Fortitude', ARRAY['Concentração', 'Eversão', 'Maldição', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 249, '{"heightened":null,"mechanics":{"object":"objeto sofre 4d6 após aplicar Dureza, fica de qualidade baixa, não pode ser Reparado e a maldição tenta neutralizar cura de PV; duração ilimitada se desapossado ou após falha do portador","construct":"sofre 4d6 com Fortitude básico; falha deixa desajeitado 1, enfraquecido 1 e sem poder ser Reparado por 1 hora; falha crítica torna a duração ilimitada","living":"criatura que não envelhece é imune; sucesso deixa desajeitado 1 e enfraquecido 1 por 1 rodada, falha por 1 hora e falha crítica por duração ilimitada","immunity":"artefatos, materiais preciosos e criaturas que não envelhecem são imunes","heightened":{"perRank":"dano aumenta em 1d6"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.mansao_resplandecente', 'Mansão Resplandecente', 'Resplendent Mansion', 'Mansión resplandeciente', 'Magia arcana ou ocultista de 9º ranque: cria uma mansão de até quatro andares com cômodos, suprimentos, servos e alarmes protegendo as entradas.', '9th-rank arcane or occult spell: creates a mansion up to four stories with rooms, supplies, servants, and alarms protecting its entrances.', 'Conjuro arcano u ocultista de rango 9: crea una mansión de hasta cuatro plantas con habitaciones, suministros, sirvientes y alarmas en sus entradas.', 9, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 'two-actions', '150 metros', NULL, 'até as próximas preparações diárias', NULL, ARRAY['Concentração', 'Estrutura', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 249, '{"heightened":null,"mechanics":{"structure":"mansão de até quatro andares e 90 metros de lado, com cômodos e decoração escolhidos pelo conjurador","mundaneObjects":"mobília e estruturas mundanas funcionam, mas deixam de existir ao sair","magic":"estruturas criadas não produzem efeitos mágicos; dispositivos mágicos levados funcionam normalmente","supplies":"contém os mesmos tipos e quantidades de alimentos e servos de Palácio Planar","alarms":"portas e janelas externas têm Alarme audível ou mental, com identificação individual"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.manada_primal', 'Manada Primal', 'Primal Herd', 'Manada primordial', 'Magia primal de 10º ranque: transforma até seis alvos em mamutes Enormes por 1 minuto, concedendo PV temporários, ataques de mamute e Atropelar.', '10th-rank primal spell: transforms up to six targets into Huge mammoths for 1 minute, granting temporary HP, mammoth attacks, and Trample.', 'Conjuro primigenio de rango 10: transforma hasta seis objetivos en mamuts Enormes durante 1 minuto, otorgando PG temporales, ataques de mamut y Arrollar.', 10, FALSE, FALSE, ARRAY['primal']::text[], 2, '9 metros', 'você e até 5 alvos voluntários', '1 minuto', NULL, ARRAY['Concentração', 'Manuseio', 'Polimorfia']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 249, '{"heightened":null,"mechanics":{"form":"cada alvo assume forma de combate Enorme de mamute e recebe o traço animal","defenses":"CA 22 + nível, 20 PV temporários, Velocidade 12 metros e visão na penumbra","attacks":"presa comprida alcance 4,5 metros 4d8+19 perfurante; tromba ágil alcance 4,5 metros 4d6+16 contundente; pata ágil alcance 4,5 metros 4d6+13 contundente","athletics":"Atletismo +30, salvo se o modificador do alvo for maior","trample":"Atropelar exige 3 ações, move até o dobro da Velocidade e usa salvamento básico de Reflexos CD 19 + nível"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.manto_de_cores', 'Manto de Cores', 'Cloak of Colors', 'Manto de colores', 'Magia de 5º ranque, arcana ou ocultista: envolve uma criatura em cores vibrantes, ofusca adjacentes e pode cegar ou atordoar atacantes corpo a corpo.', '5th-rank arcane or occult spell: surrounds a creature in vibrant colors, dazzles adjacent creatures, and can blind or stun melee attackers.', 'Conjuro arcano u ocultista de rango 5: envuelve a una criatura en colores vibrantes, deslumbra a adyacentes y puede cegar o aturdir a atacantes cuerpo a cuerpo.', 5, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 2, '9 metros', '1 criatura', '1 minuto', NULL, ARRAY['Concentração', 'Manuseio', 'Visual']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 249, '{"heightened":null,"mechanics":{"adjacent":"criaturas adjacentes ao alvo ficam ofuscadas","trigger":"criatura atinge o alvo com ataque corpo a corpo","immunity":"atacante fica temporariamente imune até o fim do turno","success":"não afetado","failure":"cego por 1 rodada","criticalFailure":"atordoado por 1 rodada"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.muralha_de_carne', 'Muralha de Carne', 'Wall of Flesh', 'Muro de carne', 'Magia de 5º ranque, divina, ocultista ou primal: cria uma muralha viva de 6 metros com seções resistentes e permite escolher bocas, olhos ou braços como característica.', '5th-rank divine, occult, or primal spell: creates a living 6-meter wall with durable sections and lets you choose mouths, eyes, or arms as its feature.', 'Conjuro divino, ocultista o primigenio de rango 5: crea una muralla viva de 6 metros con secciones resistentes y permite elegir bocas, ojos o brazos como característica.', 5, FALSE, FALSE, ARRAY['divine', 'occult', 'primal']::text[], 2, '18 metros', NULL, '1 minuto', NULL, ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 249, '{"heightened":null,"mechanics":{"wall":{"height":"6 metros","maxLength":"9 metros","thickness":"90 centímetros","section":{"length":"1,5 metros","ac":10,"hp":75}},"placement":"linha contínua sem atravessar criaturas ou objetos; não pode ser Reparada, mas pode ser curada por vitalidade e cura","mouths":"Golpeiam criaturas que terminam o turno a até 1,5 metro, usando ataque mágico e causando 2d6 perfurante; podem consumir poções","eyes":"+2 circunstancial em Percepção visual na linha de visão da muralha e permite usar os olhos como linha de visão","arms":"criaturas que terminam o turno a até 1,5 metro fazem Reflexos; falha agarrada e falha crítica restringida por 1 rodada ou até Escapar","heightened":"+2 ranques: +10 PV por seção e +1d6 no dano das bocas"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.olhos_incontaveis', 'Olhos Incontáveis', 'Countless Eyes', 'Ojos incontables', 'Magia de 4º ranque, arcana, ocultista ou primal: cobre uma criatura com olhos, impede que seja flanqueada e melhora sucessos em Buscar.', '4th-rank arcane, occult, or primal spell: covers a creature in eyes, prevents it from being flanked, and improves successes at Seek.', 'Conjuro arcano, ocultista o primigenio de rango 4: cubre a una criatura de ojos, impide que sea flanqueada y mejora sus éxitos al Buscar.', 4, FALSE, FALSE, ARRAY['arcane', 'occult', 'primal']::text[], 2, 'toque', '1 criatura', '1 minuto', NULL, ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 250, '{"heightened":null,"mechanics":{"senses":"enxerga em todas as direções ao mesmo tempo","defense":"não pode ser flanqueado","search":"sucesso em Buscar é tratado como sucesso crítico"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.onda_destruidora', 'Onda Destruidora', 'Destructive Wave', 'Onda destructiva', 'Magia de 3º ranque, arcana ou primal: lança uma onda em cone de 9 metros, causando 6d6 contundente e apagando chamas não mágicas.', '3rd-rank arcane or primal spell: sends a 9-meter cone of water dealing 6d6 bludgeoning damage and extinguishing non-magical flames.', 'Conjuro arcano o primigenio de rango 3: lanza una ola en cono de 9 metros, causa 6d6 contundente y apaga llamas no mágicas.', 3, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 2, NULL, NULL, NULL, 'Reflexos básico', ARRAY['Água', 'Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 251, '{"heightened":null,"mechanics":{"damage":"6d6 contundente","environmental":"apaga chamas não mágicas na área","heightened":"+2d6 por ranque"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.orientacao_do_andarilho', 'Orientação do Andarilho', 'Wayfinder''s Guidance', 'Guía del caminante', 'Magia divina ou ocultista de 3º ranque: guia uma viagem terrestre até um destino escolhido, reduzindo pela metade a penalidade de terreno difícil.', '3rd-rank divine or occult spell: guides overland travel to a chosen destination, halving difficult-terrain movement penalties.', 'Conjuro divino u ocultista de rango 3: guía un viaje terrestre hasta un destino elegido y reduce a la mitad las penalizaciones de terreno difícil.', 3, FALSE, FALSE, ARRAY['divine', 'occult']::text[], 'two-actions', NULL, NULL, 'até as próximas preparações diárias', NULL, ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 251, '{"heightened":null,"mechanics":{"destination":"escolhe um destino e recebe uma trajetória inspirada","travel":"você e aliados terrestres reduzem pela metade a penalidade de movimento de terreno difícil enquanto seguirem a trajetória","encounter":"não afeta movimento durante encontros","replacement":"conjurar novamente encerra e substitui a trajetória anterior"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.poco_gravitacional', 'Poço Gravitacional', 'Gravitational Well', 'Pozo gravitacional', 'Magia de 3º ranque, arcana ou ocultista: cria uma esfera gravitacional que puxa criaturas e objetos para o centro conforme o salvamento de Reflexos.', '3rd-rank arcane or occult spell: creates a gravitational sphere that pulls creatures and loose objects toward its center based on Reflex saves.', 'Conjuro arcano u ocultista de rango 3: crea una esfera gravitacional que atrae criaturas y objetos sueltos al centro según sus salvaciones de Reflejos.', 3, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 2, '36 metros', NULL, NULL, 'Reflexos', ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 251, '{"heightened":null,"mechanics":{"effect":"criaturas e objetos soltos são puxados ao centro por movimento forçado","criticalSuccess":"não afetado","success":"move 1,5 metro ao centro","failure":"move 4,5 metros ao centro","criticalFailure":"move 9 metros ao centro","spacing":"se não houver espaço no centro, mais próximos movem primeiro e os demais até onde puderem"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.passos_plumbeos', 'Passos Plúmbeos', 'Leaden Steps', 'Pasos de plomo', 'Magia de 1º ranque, arcana ou primal: transforma os pés do alvo em metal pesado, deixando-o sobrecarregado e vulnerável a eletricidade.', '1st-rank arcane or primal spell: turns a target''s feet into heavy metal, making it encumbered and vulnerable to electricity.', 'Conjuro arcano o primigenio de rango 1: convierte los pies del objetivo en metal pesado, dejándolo sobrecargado y vulnerable a electricidad.', 1, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 2, '9 metros', '1 criatura', 'sustentada até 1 minuto', 'Fortitude', ARRAY['Concentração', 'Manuseio', 'Mental', 'Morfia']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 251, '{"heightened":null,"mechanics":{"criticalSuccess":"não afetado","success":"sobrecarregado e fraqueza 2 a eletricidade até o fim do próximo turno; não pode ser sustentada","failure":"sobrecarregado e fraqueza 2 a eletricidade","criticalFailure":"sobrecarregado e fraqueza 3 a eletricidade","heightened":"+1 na fraqueza por ranque"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.presente_prestativo', 'Presente Prestativo', 'Helpful Gift', 'Regalo servicial', 'Magia de 1º ranque, arcana, divina ou ocultista: teleporta um pequeno objeto para uma criatura voluntária a até 36 metros.', '1st-rank arcane, divine, or occult spell: teleports a small object to a willing creature within 36 meters.', 'Conjuro arcano, divino u ocultista de rango 1: teletransporta un objeto pequeño a una criatura voluntaria a hasta 36 metros.', 1, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult']::text[], 1, '36 metros', '1 criatura voluntária', NULL, NULL, ARRAY['Manuseio', 'Teletransportação']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 251, '{"heightened":null,"mechanics":{"object":"teleporta objeto de Volume leve ou insignificante da mão do conjurador para a mão do alvo ou chão","failure":"falha se alvo estiver inconsciente, recusar ou se tentar teleportar criatura","awareness":"alvo sabe qual objeto está sendo enviado","heightened":{"rank3":"150 metros","rank5":"Volume 1; 3 ações alcançam 1,5 quilômetro sem linha de visão com familiaridade extrema"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.rebater_magia', 'Rebater Magia', 'Reflect Spell', 'Rebotar conjuro', 'Magia incomum de 7º ranque: como reação, tenta neutralizar uma magia que tem você como alvo e redirecioná-la ao conjurador.', 'Uncommon 7th-rank spell: as a reaction, attempts to counteract a spell targeting you and redirects it to the caster if successful.', 'Conjuro poco común de rango 7: como reacción, intenta contrarrestar un conjuro que te tiene como objetivo y lo redirige al lanzador si tiene éxito.', 7, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY['Incomum', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 251, '{"heightened":null,"mechanics":{"counteract":"tenta neutralizar a magia acionadora","redirect":"se neutralizar, a magia continua com o conjurador como alvo","limitation":"não afeta magias sem alvo específico, como magias de área"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.pele_de_camaleao', 'Pele de Camaleão', 'Chameleon Skin', 'Piel de camaleón', 'Magia primal de 5º ranque: camufla até oito criaturas paradas, concedendo +3 de estado em Furtividade para Esconder.', '5th-rank primal spell: camouflages up to eight stationary creatures, granting a +3 status bonus to Stealth to Hide.', 'Conjuro primigenio de rango 5: camufla hasta ocho criaturas inmóviles y concede +3 de estado a Sigilo para Esconderse.', 5, FALSE, FALSE, ARRAY['primal']::text[], 3, '4,5 metros', 'até 8 criaturas', '10 minutos', NULL, ARRAY['Concentração', 'Ilusão', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 251, '{"heightened":null,"mechanics":{"effect":"vestimentas e equipamento externo ajustam cores ao ambiente enquanto alvo permanece parado","stealthBonus":"+3 status em Furtividade para Esconder","removal":"remover parte do equipamento ou vestimenta encerra a magia para a criatura","heightened":{"rank6":"falha crítica ao Esgueirar a até 9 metros vira falha","rank8":"como 6º ranque e bônus +4"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.rosto_do_familiar', 'Rosto do Familiar', 'Familiar''s Face', 'Rostro del familiar', 'Magia de 3º ranque: transforma seu companheiro animal ou familiar em um sensor de vidência a até 1,5 quilômetro, permitindo perceber o mundo pelos sentidos dele enquanto sustenta a magia.', '3rd-rank spell: turns your animal companion or familiar within 1.5 kilometers into a scrying sensor whose senses you can perceive while you Sustain the Spell.', 'Conjuro de rango 3: convierte a tu compañero animal o familiar a 1,5 kilómetros en un sensor de videncia cuyos sentidos puedes percibir mientras mantienes el conjuro.', 3, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult', 'primal']::text[], 2, '1,5 quilômetro', '1 criatura voluntária que seja seu companheiro animal ou familiar', 'sustentada', NULL, ARRAY['Concentração', 'Manuseio', 'Vidência']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 251, '{"heightened":null,"mechanics":{"senses":"enxerga pelos olhos do alvo, sente os cheiros dele e percebe o mundo pelos outros sentidos","revelation":"magias de revelação que afetam os sentidos do conjurador também podem afetar o sensor","limitation":"o alvo precisa ser seu companheiro animal ou familiar e a conexão exige sustentação"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.sinestesia', 'Sinestesia', 'Synesthesia', 'Sinestesia', 'Magia ocultista de 5º ranque: reconfigura os sentidos do alvo; conforme o salvamento de Vontade, impõe distração, ocultação, desajeitado 3 e penalidade de movimento.', '5th-rank occult spell: reconfigures the target''s senses, imposing distraction, concealment, clumsy 3, and a Speed penalty based on its Will save.', 'Conjuro ocultista de rango 5: reconfigura los sentidos del objetivo e impone distracción, ocultación, torpe 3 y una penalización de Velocidades según su salvación de Voluntad.', 5, FALSE, FALSE, ARRAY['occult']::text[], 2, '9 metros', '1 criatura', 'varia conforme o salvamento', 'Vontade', ARRAY['Concentração', 'Manuseio', 'Mental']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 252, '{"heightened":null,"mechanics":{"success":"afetado por 1 rodada","failure":"afetado por 1 minuto","criticalFailure":"como falha e atordoado 2","concentration":"deve obter sucesso em teste simples CD 5 ao usar ação de concentração ou perde a ação","concealment":"todas as criaturas e objetos ficam ocultados para o alvo","movement":"desajeitado 3 e –3 metros nas Velocidades","heightened":{"rank9":"até cinco criaturas como alvo"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.sacrificio_final', 'Sacrifício Final', 'Final Sacrifice', 'Sacrificio final', 'Magia de 2º ranque: sacrifica um lacaio convocado ou controlado permanentemente para causar 6d6 de dano em uma explosão de 6 metros, com salvamento básico de Reflexos.', '2nd-rank spell: sacrifices a summoned or permanently controlled minion to deal 6d6 damage in a 6-meter burst with a basic Reflex save.', 'Conjuro de rango 2: sacrifica un lacayo convocado o controlado permanentemente para causar 6d6 de daño en una explosión de 6 metros con salvación básica de Reflejos.', 2, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult', 'primal']::text[], 2, '36 metros', '1 criatura com o traço lacaio que você convocou ou controla permanentemente', NULL, 'Reflexos básico', ARRAY['Concentração', 'Fogo', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 252, '{"heightened":null,"mechanics":{"effect":"o lacaio alvo morre imediatamente e a explosão causa 6d6 de dano de fogo em criaturas a até 6 metros","alternateDamage":"se o alvo tiver traço água ou frio, causa dano de frio e troca o traço fogo por frio","temporaryControl":"falha ao mirar criatura controlada temporariamente e rompe o efeito de controle","heightened":{"perRank":"+1 aumenta o dano em 2d6"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.salvaguarda_cintilante', 'Salvaguarda Cintilante', 'Glittering Safeguard', 'Salvaguarda centelleante', 'Magia de 6º ranque: como reação, envolve até cinco criaturas voluntárias em uma barreira que concede resistência 10 contra um tipo de dano do efeito acionador.', '6th-rank spell: as a reaction, shields up to five willing creatures with resistance 10 against one physical or energy damage type from the triggering effect.', 'Conjuro de rango 6: como reacción, protege hasta cinco criaturas voluntarias con resistencia 10 contra un tipo de daño físico o de energía del efecto desencadenante.', 6, FALSE, FALSE, ARRAY['divine', 'occult', 'primal']::text[], 'two-actions', '9 metros', 'até 5 criaturas voluntárias que sofreriam o dano', NULL, NULL, ARRAY['Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 252, '{"heightened":null,"mechanics":{"resistance":"cada alvo recebe resistência 10 contra um tipo de dano físico ou de energia escolhido para o efeito acionador","limitation":"a resistência vale apenas para o dano inicial, não para dano persistente ou outros efeitos contínuos","heightened":{"perRank":"resistência aumenta em 1"}},"needs_review":false}'::jsonb)
insert into public.catalog_spells (id, name_pt, name_en, name_es, description_pt, description_en, description_es, rank, is_cantrip, is_focus, traditions, cast_actions, range, targets, duration, defense, traits, rarity, ruleset, source_book, source_page, data)
values
  ('spell.player_core_2.schadenfreude', 'Schadenfreude', 'Schadenfreude', 'Schadenfreude', 'Magia de 1º ranque: quando você falha criticamente em um salvamento, distrai o adversário com a própria falha e pode deixá-lo estupefato.', '1st-rank spell: when you critically fail a save, distracts the adversary with its own failure and can make it stupefied.', 'Conjuro de rango 1: cuando fallas críticamente una salvación, distrae al adversario con su propio fracaso y puede dejarlo atontado.', 1, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 'two-actions', '9 metros', 'o adversário acionador', NULL, 'Vontade', ARRAY['Concentração', 'Emoção', 'Mental']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 252, '{"heightened":null,"mechanics":{"success":"sofre –1 de penalidade de estado em Percepção e Vontade por 1 rodada","failure":"fica estupefato 1 por 1 rodada","criticalFailure":"fica estupefato 2 por 1 rodada"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.selar_destino', 'Selar Destino', 'Seal Fate', 'Sellar el destino', 'Magia de 4º ranque: amaldiçoa uma criatura viva com fraqueza 2 a um tipo de dano; falhas prolongam o efeito e podem matar um alvo de 7º nível ou menor reduzido a 0 PV.', '4th-rank spell: curses a living creature with weakness 2 to a chosen damage type; failures extend the effect and can kill a level 7 or lower target reduced to 0 HP by that damage.', 'Conjuro de rango 4: maldice a una criatura viva con debilidad 2 a un tipo de daño; los fallos prolongan el efecto y pueden matar a un objetivo de nivel 7 o menor reducido a 0 PG por ese daño.', 4, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult']::text[], 2, 'toque', '1 criatura viva', NULL, 'Fortitude', ARRAY['Concentração', 'Maldição', 'Manuseio', 'Morte']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 252, '{"heightened":null,"mechanics":{"damageChoice":"escolha ácido, contundente, cortante, eletricidade, eversivo, fogo, frio, perfurante ou sônico","success":"fraqueza 2 ao tipo escolhido até o fim do próximo turno","failure":"como sucesso por 1 minuto; se criatura de 7º nível ou menor for reduzida a 0 PV pelo tipo escolhido, morre","criticalFailure":"como falha, com duração ilimitada"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.sentir_espiritos', 'Sentir Espíritos', 'Sense Spirits', 'Sentir espíritus', 'Magia divina ou ocultista de 2º ranque: detecta espíritos e assombrações em uma emanação de 9 metros, concede +1 em testes relacionados e permite comunicação através do alvo.', '2nd-rank divine or occult spell: detects spirits and haunts in a 9-meter emanation, grants +1 to related checks, and allows communication through the target.', 'Conjuro divino u ocultista de rango 2: detecta espíritus y apariciones en una emanación de 9 metros, concede +1 a pruebas relacionadas y permite comunicarse a través del objetivo.', 2, FALSE, FALSE, ARRAY['divine', 'occult']::text[], 2, NULL, NULL, '10 minutos', NULL, ARRAY['Concentração', 'Detecção', 'Manuseio', 'Mental']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 252, '{"heightened":null,"mechanics":{"detection":"permite detectar assombrações e espíritos na área mesmo sem Procurar","bonus":"+1 de bônus de estado em Percepção para Buscar, Recordar Conhecimento e perícias para determinar a razão da existência ou desabilitar assombrações","invisible":"permite Ver o Invisível enquanto ativa","communication":"pode falar através do alvo e usar Comandar um Animal como parte de Sustentar","targeting":"não exige linha de visão ou linha de efeito ao conjurar"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.solo_consagrado', 'Solo Consagrado', 'Consecrated Ground', 'Suelo consagrado', 'Magia divina de 3º ranque: consagra uma área de 3 metros e concede +1 em ataques, dano e salvamentos contra um tipo de criatura escolhido.', '3rd-rank divine spell: consecrates a 3-meter area and grants +1 to attacks, damage, and saves against a chosen creature type.', 'Conjuro divino de rango 3: consagra un área de 3 metros y concede +1 a ataques, daño y salvaciones contra un tipo de criatura elegido.', 3, FALSE, FALSE, ARRAY['divine']::text[], 3, NULL, NULL, 'até a próxima preparação diária', NULL, ARRAY['Concentração', 'Consagração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 253, '{"heightened":null,"mechanics":{"choice":"escolha aberrações, celestiais, dragões, ínferos, monitores ou mortos-vivos","benefit":"+1 de bônus de estado em ataques, dano e salvamentos contra as criaturas escolhidas"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.sussurros_eversivos', 'Sussurros Eversivos', 'Eversive Whispers', 'Susurros eversivos', 'Magia divina ou ocultista de 4º ranque: sussurra palavras que causam dano persistente eversivo e podem deixar o alvo drenado e condenado conforme o salvamento de Fortitude.', '4th-rank divine or occult spell: whispers words that deal persistent void damage and can make the target drained and doomed based on its Fortitude save.', 'Conjuro divino u ocultista de rango 4: susurra palabras que causan daño persistente de vacío y pueden dejar al objetivo drenado y condenado según su salvación de Fortaleza.', 4, FALSE, FALSE, ARRAY['divine', 'occult']::text[], 2, '18 metros', NULL, NULL, 'Fortitude', ARRAY['Auditivo', 'Concentração', 'Eversão', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 253, '{"heightened":null,"mechanics":{"success":"2d8 de dano persistente eversivo","failure":"4d8 de dano persistente eversivo e drenado 1","criticalFailure":"4d8 de dano persistente eversivo, drenado 2 e condenado 1","heightened":{"rank6":"dano persistente aumenta em 1d8 no sucesso ou 2d8 na falha/falha crítica"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.teia', 'Teia', 'Web', 'Telaraña', 'Magia arcana ou primal de 2º ranque: cria teia por 1 minuto, tornando a área terreno difícil e podendo impor penalidade de Velocidade ou imobilizar criaturas.', '2nd-rank arcane or primal spell: creates webbing for 1 minute, making the area difficult terrain and potentially penalizing Speed or immobilizing creatures.', 'Conjuro arcano o primigenio de rango 2: crea telarañas durante 1 minuto, convirtiendo el área en terreno difícil y pudiendo penalizar Velocidades o inmovilizar criaturas.', 2, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 3, '9 metros', NULL, '1 minuto', NULL, ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 253, '{"heightened":null,"mechanics":{"terrain":"quadrados tornam-se terreno difícil","movement":"criatura que inicia movimento na teia ou entra nela faz Atletismo ou Reflexos contra CD de magia para evitar penalidade de Velocidade ou ficar imobilizada","removal":"cada quadrado é removido por ataque/efeito com pelo menos 5 dano cortante ou 1 dano de fogo","square":"quadrado tem CA 5 e falha automaticamente nos salvamentos"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.tempestade_de_gelo', 'Tempestade de Gelo', 'Ice Storm', 'Tormenta de hielo', 'Magia arcana ou primal de 4º ranque: cria uma tempestade sustentada que causa dano contundente e de frio, torna a área terreno difícil e causa dano contínuo.', '4th-rank arcane or primal spell: creates a sustained storm that deals bludgeoning and cold damage, makes the area difficult terrain, and deals ongoing damage.', 'Conjuro arcano o primigenio de rango 4: crea una tormenta sostenida que causa daño contundente y de frío, convierte el área en terreno difícil y causa daño continuo.', 4, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 3, '36 metros', NULL, 'sustentada até 1 minuto', 'Reflexos básico', ARRAY['Concentração', 'Frio', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 254, '{"heightened":null,"mechanics":{"initialDamage":"2d8 contundente e 2d8 frio na conjuração","ongoing":"neve e granizo tornam a área terreno difícil; criatura que termina o turno sofre 2 dano de frio","outdoors":"ao ar livre, pode criar duas nuvens não sobrepostas; criatura Grande ou maior em ambas sofre cada dano apenas uma vez","heightened":{"rank6":"dano inicial contundente e frio aumenta em 1d8 cada e dano no fim do turno aumenta em 1"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.tempestade_de_relampagos', 'Tempestade de Relâmpagos', 'Lightning Storm', 'Tormenta de relámpagos', 'Magia primal de 5º ranque: cria uma nuvem de tempestade e convoca um raio de 4d12, podendo repetir o raio ao Sustentar a magia.', '5th-rank primal spell: creates a storm cloud and calls down a 4d12 lightning bolt, with another bolt available when you Sustain the Spell each round.', 'Conjuro primigenio de rango 5: crea una nube de tormenta y convoca un rayo de 4d12, con otro rayo disponible al mantener el conjuro cada ronda.', 5, FALSE, FALSE, ARRAY['primal']::text[], 3, '36 metros', NULL, 'sustentada até 1 minuto', 'Reflexos básico', ARRAY['Concentração', 'Eletricidade', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 254, '{"heightened":null,"mechanics":{"damage":"raio vertical causa 4d12 de dano de eletricidade em uma linha","sustain":"na primeira Sustentação de cada rodada, pode convocar outro raio na área","outdoors":"ao ar livre, pode criar duas nuvens não sobrepostas, mas ainda convoca apenas um raio por turno","heightened":{"rank7":"dano de cada raio aumenta em 1d12"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.tesouro_fantasmagorico', 'Tesouro Fantasmagórico', 'Ghostly Treasure', 'Tesoro fantasmagórico', 'Magia arcana ou ocultista de 2º ranque: cria para uma criatura viva a ilusão do que ela mais valoriza, fascinando-a ou obrigando-a a focar nela conforme o salvamento de Vontade.', '2nd-rank arcane or occult spell: creates an illusion of what a living creature values most, fascinating it or forcing it to focus on the illusion based on its Will save.', 'Conjuro arcano u ocultista de rango 2: crea para una criatura viva la ilusión de lo que más valora, fascinándola u obligándola a centrarse en ella según su salvación de Voluntad.', 2, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 2, '18 metros', '1 criatura viva', NULL, 'Vontade', ARRAY['Concentração', 'Emoção', 'Ilusão', 'Manuseio', 'Mental']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 254, '{"heightened":null,"mechanics":{"success":"fica fascinado pelo tesouro até o fim do turno e pode tentar desacreditar ao tocar, Buscar ou falar com a ilusão","failure":"como sucesso, mas duração de 1 minuto","criticalFailure":"como falha; até o fim da magia deve gastar cada ação focando no tesouro, movendo-se e Interagindo se necessário","visibility":"somente o alvo vê o tesouro; o conjurador percebe uma forma vaga"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.tragedia_fantasmagorica', 'Tragédia Fantasmagórica', 'Ghostly Tragedy', 'Tragedia fantasmagórica', 'Magia incomum de 4º ranque: reencena um evento violento recente com espíritos locais, permitindo investigação, mas causando dano eversivo ao final.', 'Uncommon 4th-rank spell: reenacts a recent violent event with local spirits, allowing investigation but dealing void damage to the caster afterward.', 'Conjuro poco común de rango 4: recrea un evento violento reciente con espíritus locales, permite investigar y causa daño de vacío al lanzador al final.', 4, FALSE, FALSE, ARRAY['divine', 'occult']::text[], 3, NULL, NULL, '10 minutos', NULL, ARRAY['Incomum', 'Concentração', 'Espírito', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 254, '{"heightened":null,"mechanics":{"reenactment":"espíritos locais reencenam evento violento recente nomeado pelo conjurador, cobrindo os 9 minutos antes da morte ou ferimento e o minuto seguinte","role":"conjurador assume o papel da vítima principal","manifestations":"espíritos de criaturas ausentes e contornos de objetos necessários aparecem conforme a cena","backlash":"ao fim, conjurador sofre 2d6 de dano eversivo por aparição fantasmagórica participante","investigation":"testemunhas podem fazer testes para investigar o evento e descobrir pistas"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.transporte_mistico', 'Transporte Místico', 'Mystic Transport', 'Transporte místico', 'Magia arcana ou ocultista de 1º ranque: cria uma plataforma de força que segue você por 8 horas e carrega até 5 Volumes.', '1st-rank arcane or occult spell: creates a force platform that follows you for 8 hours and carries up to 5 Bulk.', 'Conjuro arcano u ocultista de rango 1: crea una plataforma de fuerza que te sigue durante 8 horas y transporta hasta 5 Volúmenes.', 1, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 2, NULL, NULL, '8 horas', NULL, ARRAY['Concentração', 'Força', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 254, '{"heightened":null,"mechanics":{"platform":"plataforma invisível ou fantasmagórica de 60 cm que segue a 1,5 metro","capacity":"carrega até 5 Volumes de objetos que caibam nela","sustain":"Sustentar move até 9 metros pelo chão, mantém parada ou retorna para seguir","ending":"termina se alguém tentar subir, sobrecarregar, levantar, elevar muito ou se o conjurador ficar a mais de 18 metros","droppedItems":"objetos caem no chão quando a magia termina"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.transposicao_coletiva', 'Transposição Coletiva', 'Collective Transposition', 'Transposición colectiva', 'Magia arcana ou ocultista de 6º ranque: teleporta até duas criaturas para espaços desocupados na emanação, conforme o salvamento de Vontade.', '6th-rank arcane or occult spell: teleports up to two creatures to unoccupied spaces in the emanation based on their Will saves.', 'Conjuro arcano u ocultista de rango 6: teletransporta hasta dos criaturas a espacios desocupados de la emanación según sus salvaciones de Voluntad.', 6, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 2, NULL, 'até 2 criaturas', NULL, 'Vontade', ARRAY['Concentração', 'Manuseio', 'Teletransportação']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 255, '{"heightened":null,"mechanics":{"destination":"novas posições devem estar desocupadas, totalmente na área e na linha de visão","criticalSuccess":"alvo pode se teleportar e escolhe o destino","success":"alvo não é afetado","failure":"conjurador teleporta o alvo e escolhe o destino","heightened":{"perRank":"quantidade de alvos aumenta em 1"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.visao_animal', 'Visão Animal', 'Animal Vision', 'Visión animal', 'Magia primal de 3º ranque: acessa os sentidos de um animal por 1 hora, alternando entre eles e os próprios ao Sustentar.', '3rd-rank primal spell: accesses an animal''s senses for 1 hour, switching between them and your own when you Sustain the Spell.', 'Conjuro primigenio de rango 3: accede a los sentidos de un animal durante 1 hora y alterna entre ellos y los propios al mantenerlo.', 3, FALSE, FALSE, ARRAY['primal']::text[], 1, '36 metros', '1 animal', '1 hora', 'Vontade (se o animal desejar impedir)', ARRAY['Concentração', 'Manuseio', 'Mental']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 255, '{"heightened":null,"mechanics":{"senses":"conjurador sente tudo que o animal percebe","limitation":"enquanto acessa os sentidos do animal, não usa os próprios","sustain":"pode alternar entre sentidos próprios e do alvo usando Sustentar"},"needs_review":false}'::jsonb),
  ('spell.player_core_2.vapores_nocivos', 'Vapores Nocivos', 'Noxious Vapors', 'Vapores nocivos', 'Magia arcana ou primal de 1º ranque: cria fumaça tóxica por 1 rodada, causando veneno e ocultando criaturas dentro e fora da nuvem.', '1st-rank arcane or primal spell: creates toxic smoke for 1 round, dealing poison damage and concealing creatures inside and outside the cloud.', 'Conjuro arcano o primigenio de rango 1: crea humo tóxico durante 1 ronda, causa daño de veneno y oculta a las criaturas dentro y fuera de la nube.', 1, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 2, NULL, NULL, '1 rodada', 'Fortitude básico', ARRAY['Concentração', 'Manuseio', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 255, '{"heightened":null,"mechanics":{"damage":"1d6 de dano de veneno na conjuração para cada criatura na área, exceto o conjurador","criticalFailure":"também enjoado 1","concealment":"criaturas na área ficam ocultadas e as de fora ficam ocultadas para quem está dentro","dissipation":"vento forte pode dissipar a fumaça","heightened":{"perRank":"dano aumenta em 1d6"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.visoes_de_perigo', 'Visões de Perigo', 'Visions of Danger', 'Visiones de peligro', 'Magia ocultista de 7º ranque: cria uma ilusão de monstros em uma explosão de 9 metros, causando dano mental até que a criatura desacredite.', '7th-rank occult spell: creates an illusion of monsters in a 9-meter burst, dealing mental damage until a creature disbelieves it.', 'Conjuro ocultista de rango 7: crea una ilusión de monstruos en una explosión de 9 metros, causando daño mental hasta que una criatura la desacredite.', 7, FALSE, FALSE, ARRAY['occult']::text[], 3, '150 metros', NULL, '1 minuto', 'Vontade básico', ARRAY['Auditivo', 'Concentração', 'Ilusão', 'Manuseio', 'Visual']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 255, '{"heightened":null,"mechanics":{"damage":"8d8 de dano mental quando criada, quando criatura entra ou começa turno na explosão","disbelief":"sucesso crítico permite tentar desacreditar; Interagir ou Buscar uma criatura também permite tentar","immunityAfterDisbelief":"criaturas que desacreditam não sofrem mais dano","heightened":{"perRank":"dano mental aumenta em 1d8"}},"needs_review":false}'::jsonb),
  ('spell.player_core_2.vomitar_enxame', 'Vomitar Enxame', 'Swarm Vomit', 'Vomitar enjambre', 'Magia arcana, ocultista ou primal de 2º ranque: vomita um enxame mágico em cone, causando dano perfurante e enjoo em uma falha.', '2nd-rank arcane, occult, or primal spell: vomits a magical swarm in a cone, dealing piercing damage and sickening creatures on a failure.', 'Conjuro arcano, ocultista o primigenio de rango 2: vomita un enjambre mágico en un cono, causando daño perforante y náuseas al fallar.', 2, FALSE, FALSE, ARRAY['arcane', 'occult', 'primal']::text[], 2, NULL, NULL, NULL, 'Reflexos básico', ARRAY['Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 255, '{"heightened":null,"mechanics":{"damage":"2d8 de dano perfurante","failure":"fica enjoado 1","duration":"enxame desaparece quando a magia termina","heightened":{"perRank":"dano aumenta em 1d8"}},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.airlift', 'Transporte Aéreo', 'Airlift', 'Transporte aéreo', 'Levanta você, criaturas e itens de até Volume 10 em uma emanação de 3 metros, fazendo-os Voar até 18 metros e pousar juntos.', 'Lifts you, creatures, and items of up to Bulk 10 in a 10-foot emanation, Flying them up to 60 feet to land together.', 'Eleva a ti, criaturas y objetos de hasta Volumen 10 en una emanación de 3 metros, haciéndolos Volar hasta 18 metros para aterrizar juntos.', 4, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, 'Reflexos', ARRAY['Ar', 'Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 70, '{"heightened":null,"mechanics":{"area":"emanação de 3 metros","movement":"Voa até 18 metros","bulkLimit":"Volume 10","save":"Reflexos","heightened":"6º: 36 metros e Volume 20"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.blastback', 'Rebote Explosivo', 'Blastback', 'Rebote explosivo', 'Ao cair mais de 3 metros, impede seu dano de queda e libera uma onda que causa 6d4 contundente às outras criaturas na emanação de 6 metros, empurrando-as em uma falha.', 'When you fall more than 10 feet, you take no fall damage and release a wave dealing 6d4 bludgeoning damage to other creatures in a 20-foot emanation, pushing them on a failure.', 'Al caer más de 3 metros, no sufres daño de caída y liberas una onda que causa 6d4 contundente a otras criaturas en una emanación de 6 metros y las empuja si fallan.', 3, FALSE, FALSE, ARRAY['arcane']::text[], 'varies', NULL, NULL, NULL, 'Reflexos básico', ARRAY['Ar', 'Concentração']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 70, '{"heightened":null,"mechanics":{"trigger":"cair mais de 3 metros","area":"emanação de 6 metros","damage":"6d4 contundente","failure":"empurra 1,5 metro","save":"Reflexos básico","heightened":"+2: área +3 metros e dano +1d4"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.cleanse_air', 'Purificar Ar', 'Cleanse Air', 'Purificar aire', 'Purifica o ar em uma explosão de 9 metros, removendo venenos inalados, poluição e contaminantes e impedindo nova contaminação durante a duração.', 'Purifies air in a 30-foot burst, removing inhaled poisons, pollution, and contaminants and preventing new contamination for the duration.', 'Purifica el aire en una explosión de 9 metros, elimina venenos inhalados y contaminantes e impide nueva contaminación durante la duración.', 2, FALSE, FALSE, ARRAY['arcane', 'divine', 'primal']::text[], 'varies', '36 metros', NULL, '1 minuto', NULL, ARRAY['Ar', 'Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 70, '{"heightened":null,"mechanics":{"area":"explosão de 9 metros","duration":"1 minuto","removes":"venenos inalados, poluição e contaminantes","heightened":"3º/4º/6º/9º: área 18/36/150 metros/1,5 quilômetro"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.cloud_dragons_cloak', 'Manto do Dragão das Nuvens', 'Cloud Dragon''s Cloak', 'Manto del dragón de nubes', 'Quando você ou um aliado é alvo de um ataque à distância, uma névoa torna o alvo ocultado para resolver o ataque e os demais ataques à distância da rodada.', 'When you or an ally is targeted by a ranged attack, mist makes the target hidden for that attack and other ranged attacks for the duration.', 'Cuando tú o un aliado es objetivo de un ataque a distancia, la niebla vuelve al objetivo oculto para ese ataque y los demás ataques a distancia durante la duración.', 3, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', '18 metros', 'a criatura alvo do ataque', '1 rodada', NULL, ARRAY['Ar', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 70, '{"heightened":null,"mechanics":{"trigger":"você ou aliado ao alcance é alvo de ataque à distância","concealed":"ocultado","duration":"1 rodada","flatCheck":"CD 11 normalmente"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.deep_breath', 'Respiração Profunda', 'Deep Breath', 'Respiración profunda', 'Permite prender a respiração pela duração sem perder ar ao ser atingido; falar, inclusive conjurar magia, faz você perder o ar inalado.', 'Lets you hold your breath for the duration without losing breath when hit; speaking, including Cast a Spell, loses the inhaled air.', 'Permite contener la respiración durante la duración sin perder aire al ser golpeado; hablar, incluso lanzar un conjuro, hace perder el aire inhalado.', 1, TRUE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, '10 minutos', NULL, ARRAY['Ar', 'Cantrip', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 70, '{"heightened":null,"mechanics":{"duration":"10 minutos","limitation":"falar perde o ar inalado","heightened":"2º: 1 hora e perde apenas 10 minutos; 4º: 8 horas e perde apenas 10 minutos"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.gentle_breeze', 'Brisa Suave', 'Gentle Breeze', 'Brisa suave', 'Uma brisa em uma explosão de 12 metros concede +2 em Medicina, +2 em salvamentos contra aflições, reduz calor em um passo e cura 10 PV após a duração completa.', 'A breeze in a 40-foot burst grants +2 to Medicine and affliction saves, reduces heat effects by one step, and restores 10 HP after the full duration.', 'Una brisa en una explosión de 12 metros concede +2 a Medicina y salvaciones contra aflicciones, reduce el calor un paso y recupera 10 PG tras toda la duración.', 2, FALSE, FALSE, ARRAY['divine', 'occult', 'primal']::text[], 'varies', '18 metros', NULL, '10 minutos', NULL, ARRAY['Ar', 'Concentração', 'Cura', 'Manuseio', 'Vitalidade']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 70, '{"heightened":null,"mechanics":{"area":"explosão de 12 metros","medicineBonus":"+2 de estado","afflictionSaveBonus":"+2 de estado","healing":"10 PV","heightened":"+2: cura +10 PV"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.phantom_orchestra', 'Orquestra Fantasma', 'Phantom Orchestra', 'Orquesta fantasmal', 'Uma orquestra invisível cria uma explosão de música de 3 metros que causa 8d6 sônico; ao sustentar, você pode mover a melodia e repetir a explosão.', 'An invisible orchestra creates a 10-foot burst dealing 8d6 sonic damage; when sustained, you can move the melody and repeat the explosion.', 'Una orquesta invisible crea una explosión de 3 metros que causa 8d6 sónico; al sostenerla, puedes mover la melodía y repetir la explosión.', 6, FALSE, FALSE, ARRAY['arcane', 'occult', 'primal']::text[], 'varies', '36 metros', NULL, 'sustentada até 1 minuto', 'Fortitude básico', ARRAY['Ar', 'Concentração', 'Manuseio', 'Sônico']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 71, '{"heightened":null,"mechanics":{"range":"36 metros","area":"explosão de 3 metros","damage":"8d6 sônico","save":"Fortitude básico","duration":"sustentada até 1 minuto","heightened":"+1: dano +1d6"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.pressure_zone', 'Zona de Pressão', 'Pressure Zone', 'Zona de presión', 'Uma explosão de 6 metros reduz a pressão do ar; criaturas vivas ficam ensurdecidas e desajeitadas conforme o resultado de Fortitude.', 'A 20-foot burst drops air pressure; living creatures become deafened and clumsy based on their Fortitude save.', 'Una explosión de 6 metros reduce la presión del aire; las criaturas vivas quedan ensordecidas y torpes según su salvación de Fortaleza.', 5, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', '150 metros', NULL, '1 minuto', 'Fortitude', ARRAY['Ar', 'Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 71, '{"heightened":null,"mechanics":{"range":"150 metros","area":"explosão de 6 metros","duration":"1 minuto","save":"Fortitude","success":"ensurdecida e desajeitada 1 até o fim do próximo turno","failure":"ensurdecida e desajeitada 2","criticalFailure":"ensurdecida e desajeitada 2 pela duração","immunity":"1 hora após sair e obter sucesso"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.propulsive_breeze', 'Brisa Propulsora', 'Propulsive Breeze', 'Brisa propulsora', 'Quando um aliado ao alcance Anda ou Salta, uma corrente de vento o impulsiona 4,5 metros adicionais na mesma direção.', 'When an ally in range Strides or Leaps, a current of wind propels them an additional 15 feet in the same direction.', 'Cuando un aliado a alcance Da un paso o Salta, una corriente de viento lo impulsa 4,5 metros adicionales en la misma dirección.', 2, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', '18 metros', 'a criatura aliada que desencadeou a reação', NULL, NULL, ARRAY['Ar', 'Manuseio', 'Movimento']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 71, '{"heightened":null,"mechanics":{"trigger":"aliado ao alcance Anda ou Salta","movement":"4,5 metros adicionais","direction":"mesma direção dos últimos 1,5 metro"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.shock_to_the_system', 'Choque no Sistema', 'Shock to the System', 'Choque al sistema', 'Relâmpagos revivem um cadáver recente com 0 PV ou curam 8d8 PV, deixando o alvo acelerado e capaz de conjurar relâmpago estrondoso como magia inata.', 'Lightning revives a recent corpse at 0 Hit Points or restores 8d8 Hit Points, making the target quickened and granting innate thunderstrike.', 'Los rayos reviven un cadáver reciente con 0 PG o restauran 8d8 PG, dejando al objetivo acelerado y otorgando trueno como conjuro innato.', 7, FALSE, FALSE, ARRAY['divine', 'occult', 'primal']::text[], 'varies', '9 metros', '1 criatura viva ou 1 cadáver morto na última rodada', '1 minuto', NULL, ARRAY['Ar', 'Concentração', 'Eletricidade', 'Cura', 'Manuseio', 'Vitalidade']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 71, '{"heightened":null,"mechanics":{"targets":"1 criatura viva ou cadáver morto na última rodada","healing":"8d8 PV","revive":"retorna com 0 PV e wounded +1","quickened":"Stand, Stride, Strike ou Fly","innateSpell":"relâmpago estrondoso de 5º círculo à vontade","duration":"1 minuto","hiddenCloud":"nuvem torna criaturas dentro e fora ocultadas entre si","heightened":"+1: cura +2d8 e círculo de relâmpago +1"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.slashing_gust', 'Rajada Cortante', 'Slashing Gust', 'Ráfaga cortante', 'Com ao menos uma mão livre, ataques de magia cortam uma ou duas criaturas, causando 2d4 cortante e sangramento persistente em um acerto crítico.', 'With at least one free hand, spell attacks slash one or two creatures for 2d4 slashing damage and persistent bleed on a critical success.', 'Con al menos una mano libre, ataques de conjuro cortan a una o dos criaturas por 2d4 cortante y causan sangrado persistente en un crítico.', 1, TRUE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', '18 metros', '1 ou 2 criaturas', NULL, 'CA', ARRAY['Ar', 'Ataque', 'Cantrip', 'Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 71, '{"heightened":null,"mechanics":{"requirement":"ao menos uma mão livre","damage":"2d4 cortante","criticalSuccess":"dano dobrado e 1d4 sangramento persistente","multipleAttackPenalty":"dois ataques contam, mas a penalidade não aumenta até ambos serem feitos","heightened":"+1: dano e sangramento crítico +1d4"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.stifling_stillness', 'Imobilidade Sufocante', 'Stifling Stillness', 'Quietud sofocante', 'Uma explosão de 6 metros vira terreno difícil; criaturas que respiram ar gastam uma ação para respirar e sofrem 3d6 veneno e fadiga.', 'A 20-foot burst becomes difficult terrain; creatures that breathe air spend an action to breathe and take 3d6 poison damage and become fatigued.', 'Una explosión de 6 metros se vuelve terreno difícil; las criaturas que respiran aire gastan una acción para respirar, sufren 3d6 veneno y quedan fatigadas.', 4, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', '36 metros', NULL, '1 minuto', 'Fortitude básico', ARRAY['Ar', 'Concentração', 'Manuseio', 'Veneno']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 71, '{"heightened":null,"mechanics":{"area":"explosão de 6 metros","difficultTerrain":true,"action":"gastar 1 ação para respirar","damage":"3d6 veneno","save":"Fortitude básico","condition":"fatigada","heightened":"+2: dano +3d6"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.tempest_cloak', 'Manto da Tempestade', 'Tempest Cloak', 'Manto de tormenta', 'Ventos criam terreno difícil em uma explosão de 1,5 metro ao redor do alvo, dão +2 na CA contra ataques físicos à distância e nas defesas contra efeitos auditivos.', 'Winds create difficult terrain in a 5-foot burst around the target, granting +2 AC against physical ranged attacks and +2 defenses against auditory effects.', 'Los vientos crean terreno difícil en una explosión de 1,5 metros alrededor del objetivo, otorgando +2 a la CA contra ataques físicos a distancia y defensas contra efectos auditivos.', 3, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', '9 metros', '1 criatura disposta', '1 minuto', NULL, ARRAY['Ar', 'Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 72, '{"heightened":null,"mechanics":{"area":"explosão de 1,5 metro","difficultTerrain":true,"rangedACBonus":"+2 circunstancial","auditoryDefenseBonus":"+2 circunstancial","duration":"1 minuto"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.vacuum', 'Vácuo', 'Vacuum', 'Vacío', 'Uma emanação de 4,5 metros suga o ar; criaturas que respiram fazem Fortitude, prendem a respiração em sucesso, ficam atordoadas em falha ou começam a sufocar em falha crítica.', 'A 15-foot emanation steals the air; creatures that breathe attempt Fortitude, hold their breath on a success, become stunned on a failure, or suffocate on a critical failure.', 'Una emanación de 4,5 metros roba el aire; las criaturas que respiran hacen Fortaleza, contienen el aliento con éxito, quedan aturdidas con un fallo o empiezan a asfixiarse con un fallo crítico.', 7, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, 'sustentada até 1 minuto', 'Fortitude', ARRAY['Ar', 'Concentração', 'Incapacitação', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 72, '{"heightened":null,"mechanics":{"area":"emanação de 4,5 metros","duration":"sustentada até 1 minuto","save":"Fortitude","success":"começa a prender a respiração","failure":"Atordoada 1 e metade do ar normal","criticalFailure":"começa imediatamente a sufocar","immunity":"criaturas que não precisam respirar ar"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.voice_on_the_breeze', 'Voz na Brisa', 'Voice on the Breeze', 'Voz en la brisa', 'Sussurra uma mensagem de até 25 palavras ou uma rodada de sons para uma explosão de 3 metros familiar, seguindo um caminho de vento.', 'Whispers up to 25 words or 1 round of sounds to a familiar 10-foot burst, following a path for the wind.', 'Susurra hasta 25 palabras o 1 asalto de sonidos a una explosión familiar de 3 metros, siguiendo un camino para el viento.', 2, FALSE, FALSE, ARRAY['arcane', 'occult', 'primal']::text[], 'varies', '16 quilômetros', NULL, NULL, NULL, ARRAY['Ar', 'Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 73, '{"heightened":null,"mechanics":{"range":"16 quilômetros","area":"explosão de 3 metros","limit":"25 palavras, 1 rodada de sons ou um ruído simples","speed":"1 milha por hora a 1 milha por 10 minutos","heightened":"4º: alcance 1.000 milhas e até 100 palavras"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.wisdom_of_the_winds', 'Sabedoria dos Ventos', 'Wisdom of the Winds', 'Sabiduría de los vientos', 'Pede aos espíritos do ar uma orientação útil, seja uma rajada que guia a um destino valioso por até 8 horas ou um conselho breve.', 'You ask air spirits for useful guidance, either a gale guiding you to a valuable destination for up to 8 hours or brief advice.', 'Pides a los espíritus del aire una guía útil, ya sea una ráfaga que te conduce a un destino valioso hasta 8 horas o un consejo breve.', 5, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult', 'primal']::text[], 'varies', NULL, NULL, 'varia', NULL, ARRAY['Incomum', 'Ar', 'Concentração', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 73, '{"heightened":null,"mechanics":{"cast":"1 minuto","options":["Guiding Gale: detecção, 8 horas ou até chegar","Voice of the Sky: conselho instantâneo"],"duration":"varia","limitation":"não oferece orientação que você não possa seguir"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.air.zephyr_slip', 'Deslize do Zéfiro', 'Zephyr Slip', 'Desliz del céfiro', 'Quando uma criatura entra em um espaço adjacente, você Voa 4,5 metros diretamente para longe dela.', 'When a creature enters a space within 5 feet, you Fly 15 feet directly away from it.', 'Cuando una criatura entra en un espacio adyacente, Vuelas 4,5 metros directamente alejándote de ella.', 4, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY['Ar', 'Manuseio', 'Movimento']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 73, '{"heightened":null,"mechanics":{"trigger":"criatura entra em espaço a 1,5 metro","movement":"Voa 4,5 metros diretamente para longe","heightened":"6º: você e 1 aliado 7,5 metros; 8º: você e até 5 aliados 7,5 metros"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.burrow_ward', 'Proteção contra Escavação', 'Burrow Ward', 'Salvaguarda excavadora', 'Uma emanação de 4,5 metros solidifica a terra: criaturas que não escavam pedra não podem atravessá-la, e criaturas subterrâneas podem ser expelidas.', 'A 15-foot emanation solidifies earth: creatures that cannot burrow through stone cannot cross it, and underground creatures can be ejected.', 'Una emanación de 4,5 metros solidifica la tierra: las criaturas que no pueden excavar piedra no pueden cruzarla y las subterráneas pueden ser expulsadas.', 2, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, 'sustentada até 1 minuto', 'Fortitude', ARRAY['Concentração', 'Terra', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 94, '{"heightened":null,"mechanics":{"area":"emanação de 4,5 metros","duration":"sustentada até 1 minuto","save":"Fortitude para criatura subterrânea","effect":"expulsa criatura para a superfície em falha; sucesso força saída mas permite permanecer subterrânea","difficultTerrain":"criaturas que escavam pedra tratam como terreno difícil","heightened":"5º: emanação de 9 metros"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.exploding_earth', 'Terra Explosiva', 'Exploding Earth', 'Tierra explosiva', 'Uma esfera de terra explode no impacto, causando 4d6 contundente mais 1d6 de respingo; um acerto crítico pode derrubar o alvo.', 'A packed sphere of earth explodes on impact, dealing 4d6 bludgeoning plus 1d6 splash; a critical hit can knock the target prone.', 'Una esfera compacta de tierra explota al impactar, causando 4d6 contundente más 1d6 de salpicadura; un crítico puede derribar al objetivo.', 2, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', '36 metros', '1 criatura', NULL, 'CA; Fortitude na falha crítica', ARRAY['Concentração', 'Terra', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 94, '{"heightened":null,"mechanics":{"range":"36 metros","targets":"1 criatura","attack":"ataque de magia contra CA","damage":"4d6 contundente","splash":"1d6 contundente","critical":"dobra dano inicial, não o respingo; Fortitude ou caído","heightened":"+2: dano +2d6 e respingo +1d6"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.cave_fangs', 'Presas da Caverna', 'Cave Fangs', 'Colmillos de caverna', 'Formações de pedra surgem no chão e no teto em uma explosão de 6 metros, causando 6d6 perfurante e criando terreno difícil.', 'Stone formations protrude from the ground and ceiling in a 20-foot burst, dealing 6d6 piercing damage and creating difficult terrain.', 'Formaciones de piedra brotan del suelo y el techo en una explosión de 6 metros, causando 6d6 perforante y creando terreno difícil.', 3, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', '18 metros', NULL, '1 minuto', 'Reflexos básico', ARRAY['Concentração', 'Terra', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 94, '{"heightened":null,"mechanics":{"range":"18 metros","area":"explosão de 6 metros","damage":"6d6 perfurante","save":"Reflexos básico","difficultTerrain":true,"duration":"1 minuto; pode Desfazer","heightened":"+1: dano +2d6"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.glass_form', 'Forma de Vidro', 'Glass Form', 'Forma de vidrio', 'O alvo fica como vidro transparente: ocultado, sem cheiro, incapaz de sangrar, com resistência 5 a ácido, frio, eletricidade e perfurante e fraqueza 5 a sônico e contundente.', 'The target becomes transparent glass: hidden, scentless, unable to bleed, with resistance 5 to acid, cold, electricity, and piercing and weakness 5 to sonic and bludgeoning.', 'El objetivo se vuelve vidrio transparente: oculto, sin olor, incapaz de sangrar, con resistencia 5 a ácido, frío, electricidad y perforante y debilidad 5 a sónico y contundente.', 4, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', 'toque', '1 criatura disposta', '10 minutos', NULL, ARRAY['Concentração', 'Terra', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 94, '{"heightened":null,"mechanics":{"target":"1 criatura disposta","concealed":"ocultado","immunities":["sem cheiro","não pode sangrar"],"resistances":"5 a ácido, frio, eletricidade e perfurante","weaknesses":"5 a sônico e contundente","interaction":"afetado por shatter como objeto desacompanhado","durationReduction":"1 minuto ao sofrer dano afetado","heightened":"+2: resistências e fraquezas +5"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.engrave_memory', 'Gravar Memória', 'Engrave Memory', 'Grabar memoria', 'Armazena até 10 minutos de memória em uma pedra com palavra de comando; ao ser acessada, a pedra vira pó e a lembrança fica infalível por 24 horas.', 'Stores up to 10 minutes of memories in a stone with a command word; when accessed, the stone crumbles and the memory is infallible for 24 hours.', 'Almacena hasta 10 minutos de recuerdos en una piedra con palabra de comando; al acceder, la piedra se deshace y el recuerdo es infalible durante 24 horas.', 5, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', 'toque', '1 pedra de pelo menos Volume 1', 'ilimitada', NULL, ARRAY['Incomum', 'Concentração', 'Terra', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 94, '{"heightened":null,"mechanics":{"cast":"1 minuto","range":"toque","target":"1 pedra de pelo menos Volume 1","capacity":"até 10 minutos de material","access":"1 ação e palavra de comando","duration":"ilimitada; memória infalível por 24 horas após acesso","expiry":"pedra vira pó ao transmitir"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.glass_shield', 'Escudo de Vidro', 'Glass Shield', 'Escudo de vidrio', 'Cria um escudo de vidro com Dureza 2 e 4 PV; quando quebra, fragmentos causam 1d4 perfurante a quem estiver a 1,5 metro e falhar em Reflexos.', 'Creates a glass shield with Hardness 2 and 4 Hit Points; when it breaks, shards deal 1d4 piercing damage to a creature within 5 feet that fails Reflex.', 'Crea un escudo de vidrio con Dureza 2 y 4 PG; al romperse, los fragmentos causan 1d4 perforante a una criatura a 1,5 metros que falle Reflejos.', 1, TRUE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, 'até o início do seu próximo turno', 'Reflexos básico', ARRAY['Cantrip', 'Concentração', 'Terra']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 94, '{"heightened":null,"mechanics":{"duration":"até o início do próximo turno","shield":"Dureza 2, 4 PV","breakEffect":"Reflexos básico, 1d4 perfurante a até 1,5 metro","heightened":"3º: Dureza 4/8 PV e 1d4 + modificador; 5º: 7/16 PV e 2d4 + modificador; 7º: 10/24 PV e 3d4 + modificador; 9º: 12/32 PV e 4d4 + modificador"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.grasping_earth', 'Terra Agarradora', 'Grasping Earth', 'Tierra apresadora', 'Protrusões de rocha e solo agarram e enterram criaturas na área.', 'Rage of Elements earth spell: Grasping Earth. Full mechanical text pending review.', 'Conjuro de tierra de Rage of Elements: Tierra apresadora. El texto mecánico completo queda pendiente de revisión.', 4, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 95, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.heaving_earth', 'Terra Ondulante', 'Heaving Earth', 'Tierra ondulante', 'Uma onda atravessa o solo, sacode criaturas e explode em terra e pedras no alvo.', 'Rage of Elements earth spell: Heaving Earth. Full mechanical text pending review.', 'Conjuro de tierra de Rage of Elements: Tierra ondulante. El texto mecánico completo queda pendiente de revisión.', 7, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 95, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.instant_pottery', 'Cerâmica Instantânea', 'Instant Pottery', 'Cerámica instantánea', 'Molda material da terra em objetos simples de cerâmica temporária.', 'Rage of Elements earth spell: Instant Pottery. Full mechanical text pending review.', 'Conjuro de tierra de Rage of Elements: Cerámica instantánea. El texto mecánico completo queda pendiente de revisión.', 1, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 95, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.interposing_earth', 'Terra Interposta', 'Interposing Earth', 'Tierra interpuesta', 'Ergue uma barreira de terra para oferecer cobertura contra um ataque ou efeito de área.', 'Rage of Elements earth spell: Interposing Earth. Full mechanical text pending review.', 'Conjuro de tierra de Rage of Elements: Tierra interpuesta. El texto mecánico completo queda pendiente de revisión.', 1, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 95, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.pave_ground', 'Aplainar Solo', 'Pave Ground', 'Allanar terreno', 'Nivela o solo e remove terreno difícil não mágico feito de terra, entulho ou areia.', 'Rage of Elements earth spell: Pave Ground. Full mechanical text pending review.', 'Conjuro de tierra de Rage of Elements: Allanar terreno. El texto mecánico completo queda pendiente de revisión.', 2, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 95, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.rubble_step', 'Passo de Entulho', 'Rubble Step', 'Paso de escombros', 'Deixa um rastro de entulho que transforma os espaços abandonados em terreno difícil.', 'Rage of Elements earth spell: Rubble Step. Full mechanical text pending review.', 'Conjuro de tierra de Rage of Elements: Paso de escombros. El texto mecánico completo queda pendiente de revisión.', 2, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 96, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.sand_form', 'Forma de Areia', 'Sand Form', 'Forma de arena', 'Concede ao alvo aspectos de areia, resistência a certos danos e proteção contra sangramento.', 'Rage of Elements earth spell: Sand Form. Full mechanical text pending review.', 'Conjuro de tierra de Rage of Elements: Forma de arena. El texto mecánico completo queda pendiente de revisión.', 3, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 96, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.sliding_blocks', 'Blocos Deslizantes', 'Sliding Blocks', 'Bloques deslizantes', 'Conjura cubos de pedra que podem levitar e ser movidos para criar cobertura e obstáculos.', 'Rage of Elements earth spell: Sliding Blocks. Full mechanical text pending review.', 'Conjuro de tierra de Rage of Elements: Bloques deslizantes. El texto mecánico completo queda pendiente de revisión.', 4, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 96, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.fire.blazing_armory', 'Arsenal Flamejante', 'Blazing Armory', 'Arsenal llameante', 'Materializa uma arma simples ou marcial comum flamejante +1 striking, cujo tipo de dano muda para fogo; ela gera munição e queima quem tentar tocá-la sem ser conjurador ou alvo.', 'Materializes a common simple or martial flaming +1 striking weapon whose damage becomes fire; it generates ammunition and burns creatures that touch it without being the caster or target.', 'Materializa un arma simple o marcial común flameante +1 striking cuyo daño se vuelve fuego; genera munición y quema a quien la toque sin ser lanzador u objetivo.', 2, FALSE, FALSE, ARRAY['arcane', 'divine', 'primal']::text[], 'varies', '9 metros', '1 criatura disposta', '5 minutos', NULL, ARRAY['Concentração', 'Fogo', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 118, '{"heightened":null,"mechanics":{"range":"9 metros","target":"1 criatura disposta com mão livre","weapon":"+1 striking, dano fogo","touchDamage":"1d6 fogo para terceiros","thrown":"rematerializa na mão após Strike","heightened":"4º: até 5 alvos, flaming; 6º: +2 greater striking flaming; 8º: +3 greater striking greater flaming; 10º: +3 superior striking greater flaming"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.fire.cauterize_wounds', 'Cauterizar Ferimentos', 'Cauterize Wounds', 'Cauterizar heridas', 'Cada alvo com sangramento persistente pode sofrer 1 fogo para tentar se recuperar do sangramento com a CD menor de assistência eficaz; você pode repetir em um alvo com 1 ação.', 'Each target with persistent bleed can take 1 fire damage to attempt recovery with the lower DC for effective assistance; you can repeat it on one target with 1 action.', 'Cada objetivo con sangrado persistente puede sufrir 1 daño de fuego para intentar recuperarse con la CD menor de asistencia eficaz; puedes repetirlo en un objetivo con 1 acción.', 2, FALSE, FALSE, ARRAY['arcane', 'divine', 'primal']::text[], 'varies', '18 metros', 'até 5 criaturas dispostas', '1 minuto', NULL, ARRAY['Concentração', 'Fogo', 'Cura', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 118, '{"heightened":null,"mechanics":{"range":"18 metros","targets":"até 5 criaturas dispostas","cost":"1 dano de fogo","effect":"tenta recuperar sangramento persistente com CD menor","sustain":"1 ação com Concentração para repetir em um alvo","duration":"1 minuto"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.fire.cinder_swarm', 'Enxame de Brasas', 'Cinder Swarm', 'Enjambre de brasas', 'Um enxame de criaturas flamejantes cria uma emanação de 1,5 metro ao redor do alvo; formigas causam perfurante e fogo persistente, enquanto vaga-lumes podem ofuscar ou cegar.', 'A swarm of fiery creatures creates a 5-foot emanation around the target; ants deal piercing and persistent fire, while fireflies can dazzle or blind.', 'Un enjambre de criaturas ardientes crea una emanación de 1,5 metros alrededor del objetivo; las hormigas causan perforante y fuego persistente, mientras las luciérnagas pueden deslumbrar o cegar.', 4, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', '18 metros', '1 criatura', 'sustentada até 1 minuto', 'Fortitude ou Reflexos básico', ARRAY['Concentração', 'Fogo', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 118, '{"heightened":null,"mechanics":{"range":"18 metros","aura":"emanação de 1,5 metro","duration":"sustentada até 1 minuto","ants":"3d6 perfurante + 2d6 fogo persistente, Reflexos básico; falha empurra 1,5 metro","fireflies":"3d6 fogo, Fortitude; sucesso metade e ofuscada, falha cega 1 rodada, falha crítica cega 1 minuto","sustain":"repete efeito uma vez por rodada","heightened":"+1: dano das formigas e vaga-lumes +2d6"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.fire.dehydrate', 'Desidratar', 'Dehydrate', 'Deshidratar', 'Uma explosão de 1,5 metro causa 1d6 fogo persistente; criaturas com traço Água ou Planta pioram o resultado em um grau e fazem novos testes para ficar enfraquecidas.', 'A 5-foot burst deals 1d6 persistent fire; creatures with the water or plant trait worsen their result by one degree and attempt further saves to become enfeebled.', 'Una explosión de 1,5 metros causa 1d6 fuego persistente; las criaturas con rasgo agua o planta empeoran un grado y hacen nuevas salvaciones para quedar debilitadas.', 1, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', '9 metros', NULL, '1 minuto', 'Fortitude básico', ARRAY['Concentração', 'Fogo', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 119, '{"heightened":null,"mechanics":{"area":"explosão de 1,5 metro","damage":"1d6 fogo persistente","save":"Fortitude básico","special":"Água ou Planta piora resultado em um grau","repeat":"Fortitude no fim do turno antes do teste de recuperação; pode abrir mão se bebeu água","failure":"Enfraquecido 1 até fim do próximo turno","criticalFailure":"Enfraquecido 2 até fim do próximo turno","durationEnd":"quando o dano persistente termina","heightened":"+2: alcance +3 metros, área +1,5 metro e fogo persistente +3d6"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.fire.eat_fire', 'Comer Fogo', 'Eat Fire', 'Comer fuego', 'Quando sofreria dano de fogo, você o consome e ganha resistência 5 ao fogo até o fim do turno; depois pode expelir uma nuvem de fumaça em uma explosão de 1,5 metro.', 'When you would take fire damage, you consume it and gain fire resistance 5 until the end of the turn; you can later exhale a 5-foot smoke cloud.', 'Cuando fueras a sufrir daño de fuego, lo consumes y obtienes resistencia 5 al fuego hasta el final del turno; luego puedes exhalar una nube de humo de 1,5 metros.', 1, TRUE, FALSE, ARRAY['arcane', 'occult', 'primal']::text[], 'varies', NULL, NULL, 'até o fim do seu próximo turno', NULL, ARRAY['Cantrip', 'Fogo', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 119, '{"heightened":null,"mechanics":{"trigger":"você sofreria dano de fogo","resistance":"5 ao fogo até fim do turno","belchSmoke":"1 ação; explosão de 1,5 metro em até 6 metros, criaturas ficam ocultadas, 1 minuto","ending":"termina se ficar inconsciente, inalar ou exalar, inclusive falando","heightened":"+3: resistência +5"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.fire.falsify_heat', 'Falsificar Calor', 'Falsify Heat', 'Falsificar calor', 'Altera a temperatura aparente do alvo para moderada ou quente, enganando sentidos, concedendo +2 em Enganação para personificar criaturas e podendo ocultá-lo de visão térmica.', 'Alters the target''s apparent temperature to moderate or warm, fooling all senses, granting +2 Deception to Impersonate, and potentially hiding it from heatvision.', 'Altera la temperatura aparente del objetivo a moderada o cálida, engañando todos los sentidos, otorgando +2 a Engaño para Impersonar y pudiendo ocultarlo de visión térmica.', 2, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', '18 metros', '1 criatura disposta ou objeto', '8 horas', NULL, ARRAY['Concentração', 'Fogo', 'Ilusão', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 119, '{"heightened":null,"mechanics":{"range":"18 metros","target":"1 criatura disposta ou objeto","moderate":"+2 circunstancial para personificar morto-vivo, sangue-frio ou objeto; invisível a heatvision","warm":"+2 circunstancial para personificar criatura de sangue quente","duration":"8 horas; pode Desfazer","heightened":"4º: até 10 criaturas, temperaturas diferentes"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.fire.fires_pathway', 'Caminho do Fogo', 'Fire''s Pathway', 'Camino del fuego', 'Após 1 minuto, entra em um fogo grande o bastante para você e teletransporta-se para outro fogo suficientemente grande em até 8 quilômetros.', 'After 1 minute, you enter a fire large enough for you and teleport to another sufficiently large fire within 5 miles.', 'Tras 1 minuto, entras en un fuego lo bastante grande y te teletransportas a otro fuego suficientemente grande a 8 kilómetros.', 5, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY['Incomum', 'Concentração', 'Fogo', 'Manuseio', 'Teletransporte']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 119, '{"heightened":null,"mechanics":{"cast":"1 minuto","range":"8 quilômetros","condition":"fogo de entrada e saída grande o bastante","limitation":"não leva espaços extradimensionais","heightened":"6º: 80 quilômetros; 8º: 800 quilômetros; 9º: qualquer ponto no mesmo planeta"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.fire.fireproof', 'À Prova de Fogo', 'Fireproof', 'Resistente al fuego', 'Impede o objeto de conduzir calor ou pegar fogo, concede resistência 10 a fogo e exige contramágica contra efeitos de Fogo que o tenham como alvo.', 'Prevents an object from conducting heat or catching fire, grants fire resistance 10, and requires counteract checks against fire effects targeting it.', 'Impide que un objeto conduzca calor o arda, otorga resistencia 10 al fuego y exige pruebas de contrarrestar contra efectos de fuego que lo tengan como objetivo.', 2, FALSE, FALSE, ARRAY['arcane', 'divine', 'primal']::text[], 'varies', 'toque', '1 objeto de até Volume 10', '1 hora', NULL, ARRAY['Concentração', 'Fogo', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 119, '{"heightened":null,"mechanics":{"cast":"1 minuto","target":"1 objeto de até Volume 10","duration":"1 hora","resistance":"10 ao fogo","counteract":"efeitos com traço Fogo contra o objeto","heightened":"4º: 24 horas; 6º: ilimitada"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.fire.flame_dancer', 'Dançarino das Chamas', 'Flame Dancer', 'Danzante de llamas', 'Fogo envolve mãos, pés, olhos e cabelo; Golpes desarmados causam +2d6 fogo e acertos críticos causam +2d4 fogo persistente, além de permitir Desmoralizar com Atuação.', 'Fire surrounds the target; unarmed Strikes deal +2d6 fire and critical hits deal +2d4 persistent fire, and the target can Demoralize with Performance.', 'El fuego rodea al objetivo; los Golpes sin armas causan +2d6 fuego y los críticos +2d4 fuego persistente, y puede Desmoralizar con Interpretación.', 5, FALSE, FALSE, ARRAY['arcane', 'occult', 'primal']::text[], 'varies', '18 metros', '1 criatura disposta', '1 minuto', NULL, ARRAY['Concentração', 'Fogo', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 120, '{"heightened":null,"mechanics":{"range":"18 metros","unarmedDamage":"+2d6 fogo","criticalPersistent":"+2d4 fogo persistente","demoralize":"pode usar Atuação em vez de Intimidação; perde auditivo e ganha visual","duration":"1 minuto","heightened":"7º: dano +3d6, persistente +3d4; crítico de Atuação deixa alvo fleeing 1 rodada"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.fire.flames_of_ego', 'Chamas do Ego', 'Flames of Ego', 'Llamas del ego', 'Chamas elegantes tornam o alvo fascinado por si mesmo e exigem uma exibição de arrogância; uma falha também impede hostilidade até ser atacado.', 'Elegant flames make the target fascinated with itself and require an arrogant display; on a failure it cannot act hostile until attacked.', 'Llamas elegantes hacen que el objetivo se fascine consigo mismo y exigen una exhibición arrogante; con un fallo no puede actuar hostilmente hasta ser atacado.', 5, FALSE, FALSE, ARRAY['arcane', 'occult', 'primal']::text[], 'varies', '36 metros', '1 criatura', 'varia', 'Vontade', ARRAY['Concentração', 'Fogo', 'Incapacitação', 'Luz', 'Manuseio', 'Mental']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 120, '{"heightened":null,"mechanics":{"range":"36 metros","save":"Vontade","success":"luz brilhante em emanação de 6 metros, fascinado 1 rodada e gasta 1 ação em exibição","failure":"como sucesso por 1 minuto; não age hostil até sofrer hostilidade","criticalFailure":"como falha, gasta pelo menos 2 ações","duration":"varia"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.fire.heatvision', 'Visão Térmica', 'Heatvision', 'Visión térmica', 'Concede visão infravermelha precisa a 18 metros, detectando calor, frio, criaturas de sangue quente e quase todas com traço Frio ou Fogo através de fumaça e escuridão.', 'Grants precise infrared vision to 60 feet, detecting heat, cold, warm-blooded creatures, and nearly all creatures with cold or fire traits through smoke and darkness.', 'Otorga visión infrarroja precisa a 18 metros, detectando calor, frío, criaturas de sangre caliente y casi todas con rasgo frío o fuego a través de humo y oscuridad.', 3, FALSE, FALSE, ARRAY['arcane', 'divine', 'occult', 'primal']::text[], 'varies', 'toque', '1 criatura disposta', '1 hora', NULL, ARRAY['Incomum', 'Concentração', 'Fogo', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 120, '{"heightened":null,"mechanics":{"range":"toque","target":"1 criatura disposta","duration":"1 hora","sense":"visão infravermelha precisa a 18 metros","limitation":"mortos-vivos e constructos normalmente não são detectados","heightened":"6º: até próximas preparações diárias e alcance 36 metros"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.fire.illuminate', 'Iluminar', 'Illuminate', 'Iluminar', 'Acende fontes não mágicas de luz que usam fogo em uma emanação de até 9 metros; criatura que atende a fonte pode tentar Reflexos para apagá-la.', 'Lights nonmagical fire-based light sources in a 30-foot emanation; a creature attending a source can attempt Reflex to snuff it before it is noticeable.', 'Enciende fuentes de luz no mágicas que usan fuego en una emanación de 9 metros; una criatura que atienda la fuente puede intentar Reflejos para apagarla.', 1, TRUE, FALSE, ARRAY['arcane', 'divine', 'occult', 'primal']::text[], 'varies', NULL, NULL, NULL, 'Reflexos', ARRAY['Cantrip', 'Fogo', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 120, '{"heightened":null,"mechanics":{"area":"emanação de até 9 metros, ajustável menor","effect":"acende velas, lâmpadas e fontes não mágicas de luz a fogo","save":"Reflexos para criatura disposta a apagar a fonte","heightened":"+1: área máxima +3 metros"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.fire.phoenix_ward', 'Proteção da Fênix', 'Phoenix Ward', 'Protección del fénix', 'Concede resistência 10 a fogo; se dano de fogo o reduzir a 0 PV, absorve o excesso, cura 4d8 mais o dano absorvido e termina, sem poder ser lançado novamente por 24 horas.', 'Grants fire resistance 10; if fire damage would reduce you to 0 Hit Points, it absorbs excess damage, heals 4d8 plus the absorbed damage, and ends for 24 hours.', 'Otorga resistencia 10 al fuego; si el daño de fuego te redujera a 0 PG, absorbe el exceso, cura 4d8 más el daño absorbido y termina durante 24 horas.', 4, FALSE, FALSE, ARRAY['divine', 'primal']::text[], 'varies', NULL, NULL, '1 minuto', NULL, ARRAY['Concentração', 'Fogo', 'Manuseio']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 120, '{"heightened":null,"mechanics":{"duration":"1 minuto","resistance":"10 ao fogo","trigger":"dano de fogo reduzir a 0 PV","healing":"4d8 + dano absorvido, efeito de vitalidade","cooldown":"não pode lançar novamente por 24 horas","heightened":"+1: cura +1d8"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.beheading_buzz_saw', 'Serra Zumbidora Decapitante', 'Beheading Buzz Saw', 'Sierra decapitadora', 'Uma serra de sucata derretida percorre uma linha de 18 metros, causando 5d10 cortante e 4d6 sangramento persistente; uma falha crítica pode decapitar.', 'A saw of molten scrap travels in an 60-foot line, dealing 5d10 slashing and 4d6 persistent bleed; a critical failure can decapitate.', 'Una sierra de chatarra fundida recorre una línea de 18 metros, causando 5d10 cortante y 4d6 sangrado persistente; un fallo crítico puede decapitar.', 7, FALSE, FALSE, ARRAY['arcane']::text[], 'varies', NULL, NULL, NULL, 'Reflexos; Fortitude na falha crítica', ARRAY['Concentração', 'Manuseio', 'Metal']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 142, '{"heightened":null,"mechanics":{"area":"linha de 18 metros","damage":"5d10 cortante + 4d6 sangramento persistente","save":"Reflexos","criticalFailure":"dano dobrado; Fortitude ou decapitado, com morte e incapacitação","heightened":"+1: cortante +1d10 e sangramento +1d6"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.conductive_weapon', 'Arma Condutiva', 'Conductive Weapon', 'Arma conductora', 'A arma de metal torna-se uma arma shock +1; contra alvo com armadura de metal ou feito principalmente de metal, o dado elétrico da runa é d12.', 'The metal weapon becomes a +1 shock weapon; against a target in metal armor or primarily made of metal, its shock rune electricity die is d12.', 'El arma metálica se vuelve un arma shock +1; contra un objetivo con armadura metálica o hecho principalmente de metal, el dado eléctrico de la runa es d12.', 1, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', 'toque', '1 arma de metal', '1 minuto', NULL, ARRAY['Concentração', 'Eletricidade', 'Manuseio', 'Metal']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 142, '{"heightened":null,"mechanics":{"target":"arma de metal desacompanhada ou empunhada por você/aliado disposto","duration":"1 minuto","weapon":"+1 shock","special":"dado elétrico d12 contra armadura de metal ou criatura principalmente metálica"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.detect_metal', 'Detectar Metal', 'Detect Metal', 'Detectar metal', 'Uma emanação de 9 metros revela presença ou ausência de objetos, veios e depósitos metálicos, podendo ignorar o metal conhecido do seu equipamento.', 'A 30-foot emanation reveals the presence or absence of metallic objects, veins, and deposits, and can ignore metal you already know about.', 'Una emanación de 9 metros revela presencia o ausencia de objetos, vetas y depósitos metálicos, pudiendo ignorar el metal que ya conoces.', 1, TRUE, FALSE, ARRAY['arcane', 'divine', 'occult', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY['Cantrip', 'Concentração', 'Detecção', 'Manuseio', 'Metal']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 142, '{"heightened":null,"mechanics":{"area":"emanação de 9 metros","detects":"presença/ausência de objetos, veios e depósitos metálicos","illusion":"detecta metal oculto por ilusão de ranque inferior; nota ausência em objeto não metálico disfarçado","limitation":"não identifica tipo quando um metal é disfarçado como outro","heightened":"3º: identifica todos os tipos e supera ilusão enganosa de ranque inferior"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.clad_in_metal', 'Revestir com Metal', 'Clad in Metal', 'Revestir de metal', 'Troca temporariamente a superfície de um objeto de metal por metal precioso comum, fazendo-o funcionar como item desse metal até nível 2.', 'Temporarily swaps an object''s metal surface for common precious metal, making it function as an item of that metal up to 2nd level.', 'Cambia temporalmente la superficie metálica de un objeto por metal precioso común, haciéndolo funcionar como objeto de ese metal hasta nivel 2.', 2, FALSE, FALSE, ARRAY['arcane', 'divine', 'primal']::text[], 'varies', 'toque', '1 objeto de metal de até Volume 5', '1 minuto', NULL, ARRAY['Concentração', 'Manuseio', 'Metal']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 142, '{"heightened":null,"mechanics":{"target":"objeto de metal de até Volume 5, desacompanhado ou com criatura disposta","duration":"1 minuto","effect":"funciona como metal precioso de item até nível 2","examples":"adaga pode virar ferro frio ou prata; armadura completa não","properties":"ativa fraquezas do metal e suprime propriedades do metal original","heightened":"+1: nível máximo do metal +2"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.ferrous_form', 'Forma Ferrosa', 'Ferrous Form', 'Forma ferrosa', 'Transforma o corpo em ferro flexível, concedendo resistência 10 a dano físico salvo adamantina, várias imunidades, golpes de punho d10 e grande densidade.', 'Transforms the body into flexible iron, granting resistance 10 to physical damage except adamantine, many immunities, d10 fists, and great density.', 'Transforma el cuerpo en hierro flexible, otorgando resistencia 10 al daño físico salvo adamantina, varias inmunidades, puños d10 y gran densidad.', 8, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, '1 hora', NULL, ARRAY['Concentração', 'Metal', 'Manuseio', 'Polimorfia']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 142, '{"heightened":null,"mechanics":{"duration":"1 hora","resistance":"10 a físico exceto adamantina","immunities":"morte, doença, drenado, fatigado, cura, não letal, paralisado, veneno, doente, vitalidade e vazio","fists":"d10","bulk":"dobra, 6 se Pequeno ou 12 se Médio","movement":"não precisa respirar; afunda na água; sujeita a rust cloud","heightened":"9º: resistência 15"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.field_of_razors', 'Campo de Lâminas', 'Field of Razors', 'Campo de navajas', 'Cria uma explosão de 6 metros de fios metálicos cortantes que é terreno difícil e causa 5 cortante por quadrado atravessado; sangue pode expandi-la.', 'Creates a 20-foot burst of razor wires that is difficult terrain and deals 5 slashing per square traversed; blood can expand it.', 'Crea una explosión de 6 metros de alambres cortantes que es terreno difícil y causa 5 cortante por casilla atravesada; la sangre puede expandirla.', 6, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', '18 metros', NULL, '1 minuto', 'Reflexos básico', ARRAY['Concentração', 'Manuseio', 'Metal']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 143, '{"heightened":null,"mechanics":{"range":"18 metros","area":"explosão de 6 metros","damage":"5 cortante por quadrado","difficultTerrain":true,"duration":"1 minuto","reaction":"ao sofrer cortante, perfurante ou sangramento dentro, expande 1,5 metro; até 4 vezes, máximo 12 metros","material":"metal escolhido retorna ao fim","heightened":"+1: dano por quadrado +2"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.fold_metal', 'Dobrando Metal', 'Fold Metal', 'Doblar metal', 'Dobra um objeto metálico para formar uma esfera lisa do tamanho de um ovo; água, fogo, Desfazer ou o fim da duração restauram sua forma.', 'Folds an unattended metal object into a smooth egg-sized ball; water, fire, Dismiss, or the duration restores its shape.', 'Dobla un objeto metálico desatendido en una esfera lisa del tamaño de un huevo; agua, fuego, Descartar o la duración restauran su forma.', 1, FALSE, FALSE, ARRAY['arcane']::text[], 'varies', 'toque', '1 objeto metálico desacompanhado de até Volume 5', '10 minutos', NULL, ARRAY['Concentração', 'Manuseio', 'Metal']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 143, '{"heightened":null,"mechanics":{"target":"objeto metálico de até Volume 5","duration":"10 minutos","shape":"esfera lisa não maior que ovo","ending":"Desfazer, fim da duração, tocar água ou fogo","notice":"Percepção contra CD da magia para notar disfarce","magical":"mantém auras, mas não pode ser vestido, afixado ou ativado","heightened":"3º: duração 1 hora"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.magnetic_dominion', 'Domínio Magnético', 'Magnetic Dominion', 'Dominio magnético', 'Uma emanação de 30 metros reposiciona criaturas com armadura metálica, feitas de metal ou com traço Metal, e objetos metálicos; você pode mover um alvo ao sustentar.', 'A 100-foot emanation relocates creatures in metal armor, made of metal, or with the metal trait, and unattended metal objects; you can move one target when sustained.', 'Una emanación de 30 metros reposiciona criaturas con armadura metálica, hechas de metal o con rasgo Metal, y objetos metálicos; puedes mover un objetivo al sostener.', 9, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, 'qualquer número de alvos metálicos', 'sustentada até 1 minuto', 'Reflexos', ARRAY['Concentração', 'Manuseio', 'Metal']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 143, '{"heightened":null,"mechanics":{"area":"emanação de 30 metros","targets":"qualquer número de criaturas/objetos metálicos","save":"Reflexos para alvo unwilling","effect":"reloca cada alvo a espaço desocupado na emanação; alvos movem juntos","sustain":"move 1 criatura","selfEffect":"pode receber magnetic repulsion de 8º círculo","duration":"sustentada até 1 minuto"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.mantle_of_the_melting_heart', 'Manto do Coração Derretido', 'Mantle of the Melting Heart', 'Manto del corazón fundido', 'Um manto de metal líquido permite escolher duas propriedades: resistência a eletricidade e contramágica, imunidade a veneno/doença ou toque corrosivo, ou punhos com alcance e agarrar.', 'A liquid metal mantle lets you choose two properties: electricity resistance and counteract protection, poison and disease immunity, corrosive touch, or reach-and-grab fists.', 'Un manto de metal líquido permite elegir dos propiedades: resistencia a electricidad y protección de contrarrestar, inmunidad a veneno/enfermedad, toque corrosivo o puños con alcance y agarrar.', 5, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, '1 minuto', NULL, ARRAY['Concentração', 'Manuseio', 'Metal', 'Morfia']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 143, '{"heightened":null,"mechanics":{"duration":"1 minuto","choices":"escolhe 2 opções; 1 ação Concentration troca uma","copperCore":"resistência 10 eletricidade; efeitos elétricos em 9 metros fazem contramágica para afetar só você","goldenFlesh":"imune a veneno/doença e +2 circunstancial contra efeitos atuais","reactiveTouch":"metal tocado causa 2d6 ácido que ignora Dureza","weightedGrasp":"punho cablado 1d4 contundente +1d6 veneno, desarmar/finesse/alcance/agarrar/derrubar"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.mercurial_stride', 'Passo Mercurial', 'Mercurial Stride', 'Paso mercurial', 'Assume forma líquida de mercúrio, Anda até o dobro da velocidade e atravessa um espaço de criatura, expondo-a a veneno de mercúrio com Fortitude.', 'Takes a liquid mercury form, Strides up to twice your Speed, and passes through one creature''s space, exposing it to mercury poison with Fortitude.', 'Adopta forma líquida de mercurio, Avanza hasta el doble de tu Velocidad y atraviesa el espacio de una criatura, exponiéndola a veneno de mercurio con Fortaleza.', 4, FALSE, FALSE, ARRAY['arcane', 'occult']::text[], 'varies', NULL, NULL, NULL, 'Fortitude', ARRAY['Concentração', 'Manuseio', 'Metal', 'Veneno']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 144, '{"heightened":null,"mechanics":{"movement":"Anda até o dobro da velocidade","passage":"atravessa um espaço sem teste de Acrobacia, não termina nele","save":"Fortitude","success":"Enjoado 1","failure":"Enjoado 2 e 6d6 veneno","criticalFailure":"Enjoado 2 e 12d6 veneno","heightened":"+1: dano de falha +1d6 e falha crítica +2d6"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.needle_darts', 'Dardos de Agulha', 'Needle Darts', 'Dardos de aguja', 'Molda três agulhas de metal contra uma criatura, causando 3d4 perfurante e podendo causar sangramento persistente; o metal retorna depois.', 'Shapes three metal needles at one creature, dealing 3d4 piercing and potentially persistent bleed; the metal returns afterward.', 'Moldea tres agujas de metal contra una criatura, causando 3d4 perforante y pudiendo causar sangrado persistente; el metal regresa después.', 1, TRUE, FALSE, ARRAY['arcane', 'divine', 'occult', 'primal']::text[], 'varies', '18 metros', '1 criatura', NULL, 'CA', ARRAY['Ataque', 'Cantrip', 'Concentração', 'Manuseio', 'Metal']::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 144, '{"heightened":null,"mechanics":{"range":"18 metros","targets":"1 criatura","attack":"ataque de magia contra CA","damage":"3d4 perfurante","metalProperties":"aplica propriedades especiais do metal","criticalSuccess":"dano dobrado e 1 sangramento persistente","success":"dano completo","heightened":"+1: uma agulha adicional, dano +1d4 e sangramento crítico +1"},"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.noxious_metals', 'Metais Nocivos', 'Noxious Metals', 'Metales nocivos', 'Libera vapores metálicos tóxicos que deixam criaturas doentes e causam dano de veneno.', 'Rage of Elements metal spell: Noxious Metals. Full mechanical text pending review.', 'Conjuro de metal de Rage of Elements: Metales nocivos. El texto mecánico completo queda pendiente de revisión.', 3, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 145, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.rust_cloud', 'Nuvem de Ferrugem', 'Rust Cloud', 'Nube de óxido', 'Uma nuvem corrosiva enferruja metal e ameaça criaturas e objetos na área.', 'Rage of Elements metal spell: Rust Cloud. Full mechanical text pending review.', 'Conjuro de metal de Rage of Elements: Nube de óxido. El texto mecánico completo queda pendiente de revisión.', 4, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 145, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.shielded_arm', 'Braço Protegido', 'Shielded Arm', 'Brazo protegido', 'Cria um escudo metálico no braço para bloquear um ataque ou efeito iminente.', 'Rage of Elements metal spell: Shielded Arm. Full mechanical text pending review.', 'Conjuro de metal de Rage of Elements: Brazo protegido. El texto mecánico completo queda pendiente de revisión.', 1, FALSE, FALSE, ARRAY['arcane', 'divine', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 145, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.wall_of_metal', 'Muralha de Metal', 'Wall of Metal', 'Muro de metal', 'Ergue uma muralha metálica resistente que permanece até ser destruída ou a magia terminar.', 'Rage of Elements metal spell: Wall of Metal. Full mechanical text pending review.', 'Conjuro de metal de Rage of Elements: Muro de metal. El texto mecánico completo queda pendiente de revisión.', 6, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 146, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.water.brine_dragon_bile', 'Bile de Dragão de Salmoura', 'Brine Dragon Bile', 'Bilis de dragón de salmuera', 'Fere uma criatura que acabou de sofrer um ataque cortante ou perfurante, causando dano persistente de ácido.', 'Rage of Elements water spell: Brine Dragon Bile. Full mechanical text pending review.', 'Conjuro de agua de Rage of Elements: Bilis de dragón de salmuera. El texto mecánico completo queda pendiente de revisión.', 2, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 172, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.water.buoyant_bubbles', 'Bolhas Flutuantes', 'Buoyant Bubbles', 'Burbujas flotantes', 'Reveste uma criatura com bolhas que a fazem flutuar e impedem que afunde.', 'Rage of Elements water spell: Buoyant Bubbles. Full mechanical text pending review.', 'Conjuro de agua de Rage of Elements: Burbujas flotantes. El texto mecánico completo queda pendiente de revisión.', 1, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 172, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.water.coral_scourge', 'Flagelo de Coral', 'Coral Scourge', 'Azote de coral', 'Faz coral crescer sobre uma criatura, deixando-a desajeitada e restringindo seu movimento.', 'Rage of Elements water spell: Coral Scourge. Full mechanical text pending review.', 'Conjuro de agua de Rage of Elements: Azote de coral. El texto mecánico completo queda pendiente de revisión.', 3, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 172, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.water.dancing_fountain', 'Fonte Dançante', 'Dancing Fountain', 'Fuente danzante', 'Cria uma fonte que pode mover criaturas, obscurecer a área ou causar dano em uma explosão.', 'Rage of Elements water spell: Dancing Fountain. Full mechanical text pending review.', 'Conjuro de agua de Rage of Elements: Fuente danzante. El texto mecánico completo queda pendiente de revisión.', 7, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 172, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.water.dive_and_breach', 'Mergulho e Emergência', 'Dive and Breach', 'Inmersión y salida', 'Teletransporta você entre superfícies como um mergulho, causando dano nas áreas de entrada e saída.', 'Rage of Elements water spell: Dive and Breach. Full mechanical text pending review.', 'Conjuro de agua de Rage of Elements: Inmersión y salida. El texto mecánico completo queda pendiente de revisión.', 3, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 172, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.water.draw_moisture', 'Extrair Umidade', 'Draw Moisture', 'Extraer humedad', 'Extrai água de um objeto para secá-lo ou obter uma pequena quantidade de água potável.', 'Rage of Elements water spell: Draw Moisture. Full mechanical text pending review.', 'Conjuro de agua de Rage of Elements: Extraer humedad. El texto mecánico completo queda pendiente de revisión.', 1, FALSE, FALSE, ARRAY['arcane', 'divine', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 173, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.water.freezing_rain', 'Chuva Congelante', 'Freezing Rain', 'Lluvia congelante', 'Cria chuva que torna a área difícil e pode congelar para causar dano de frio e lentidão.', 'Rage of Elements water spell: Freezing Rain. Full mechanical text pending review.', 'Conjuro de agua de Rage of Elements: Lluvia congelante. El texto mecánico completo queda pendiente de revisión.', 5, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 173, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.water.frost_pillar', 'Pilar de Gelo', 'Frost Pillar', 'Pilar de escarcha', 'Aprisiona uma criatura em um pilar de gelo resistente até que ele seja destruído ou a magia termine.', 'Rage of Elements water spell: Frost Pillar. Full mechanical text pending review.', 'Conjuro de agua de Rage of Elements: Pilar de escarcha. El texto mecánico completo queda pendiente de revisión.', 6, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'varies', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 173, '{"heightened":null,"needs_review":false}'::jsonb),
