values
  ('pet.wolf', 'Lobo', 'Wolf Companion', 'Compañero lobo', 'Companheiro veloz que ajuda a flanquear e derrubar inimigos.', 'Fast companion that helps flank and trip enemies.', 'Compañero veloz que ayuda a flanquear y derribar enemigos.', 'animal_companion', 'Pequeno ou Médio', '40 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"hp_base":6,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
