  ('pet.horse', 'Cavalo', 'Horse Companion / Mount', 'Compañero caballo / Montura', 'Montaria veloz para investidas e combate montado.', 'Fast mount for charges and mounted combat.', 'Montura veloz para cargas y combate montado.', 'animal_companion', 'Grande', '40 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"hp_base":8,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.bird', 'Pássaro / Coruja', 'Bird Companion', 'Compañero ave', 'Companheiro voador ágil para reconhecimento e ataques precisos.', 'Agile flying companion for scouting and precise attacks.', 'Compañero volador ágil para explorar y atacar con precisión.', 'animal_companion', 'Pequeno', '10 pés, Voo 60 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"hp_base":4,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.big_cat', 'Gato Grande / Pantera', 'Big Cat', 'Gran felino / Pantera', 'Companheiro furtivo que ajuda a deixar inimigos desprevenidos.', 'Stealthy companion that helps leave enemies off-guard.', 'Compañero sigiloso que ayuda a dejar desprevenidos a los enemigos.', 'animal_companion', 'Pequeno ou Médio', '35 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"hp_base":6,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.dromaeosaur', 'Dromaeossauro', 'Dromaeosaur Companion', 'Compañero dromeosaurio', 'Companheiro veloz especializado em cercar e flanquear inimigos.', 'Fast companion specialized in surrounding and flanking enemies.', 'Compañero veloz especializado en rodear y flanquear enemigos.', 'animal_companion', 'Pequeno', '50 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 207, '{"hp_base":6,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.badger', 'Texugo', 'Badger Companion', 'Compañero tejón', 'Companheiro resistente que cava e causa dano contínuo.', 'Sturdy companion that burrows and deals persistent damage.', 'Compañero resistente que excava y causa daño persistente.', 'animal_companion', 'Pequeno', '25 pés, Escavação 10 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"hp_base":8,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.familiar', 'Familiar Arcano / Místico', 'Familiar', 'Familiar arcano / místico', 'Familiar que concede habilidades escolhidas ao seu mestre.', 'A familiar that grants chosen abilities to its master.', 'Familiar que concede habilidades elegidas a su amo.', 'animal_companion', 'Minúsculo', '25 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 212, '{"hp_base":5,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.antelope', 'Antílope', 'Antelope', 'Antílope', 'Companheiro veloz e montável que pode causar sangramento persistente.', 'A swift mount companion that can cause persistent bleed damage.', 'Compañero veloz y montable que puede causar daño persistente por sangrado.', 'animal_companion', 'Médio ou Grande', '40 pés', '[{"name":"Chifres","bonus":"—","damage":"1d6 perfurante","traits":["Acurada"]},{"name":"Casco","bonus":"—","damage":"1d4 impacto","traits":["Ágil","Acurada"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 91, '{"hp_base":6,"support_benefit":"Enquanto montado, Golpes que causam dano no alcance do antílope também causam 1d6 de sangramento persistente até o início do seu próximo turno.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.elk', 'Alce', 'Elk', 'Alce', 'Companheiro montável que intimida inimigos com seus chifres.', 'A mount companion that frightens enemies with its antlers.', 'Compañero montable que asusta a los enemigos con sus astas.', 'animal_companion', 'Médio ou Grande', '30 pés', '[{"name":"Chifres","bonus":"—","damage":"1d8 perfurante","traits":[]},{"name":"Casco","bonus":"—","damage":"1d6 impacto","traits":["Ágil"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 91, '{"hp_base":8,"support_benefit":"Até o início do seu próximo turno, se você atingir e causar dano a uma criatura no alcance do alce, ela fica Amedrontada 1.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.flying_squirrel', 'Esquilo Voador', 'Flying Squirrel', 'Ardilla voladora', 'Companheiro que plana e dificulta o deslocamento dos inimigos.', 'A companion that glides and hampers enemy movement.', 'Compañero que planea y dificulta el movimiento enemigo.', 'animal_companion', 'Pequeno', '25 pés, escalada 25 pés', '[{"name":"Mandíbulas","bonus":"—","damage":"1d6 perfurante","traits":["Acurada"]},{"name":"Garra","bonus":"—","damage":"1d4 cortante","traits":["Ágil","Acurada"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 92, '{"hp_base":6,"support_benefit":"Até o fim do seu próximo turno, um alvo atingido por seu Golpe no alcance do esquilo sofre –10 pés de penalidade de circunstância em seus Deslocamentos por 1 rodada.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.giraffe', 'Girafa', 'Giraffe', 'Jirafa', 'Companheiro montável de pescoço longo que amplia manobras de Empurrar.', 'A long-necked mount that improves Shove maneuvers.', 'Montura de cuello largo que mejora las maniobras de Empujar.', 'animal_companion', 'Grande', '35 pés', '[{"name":"Casco","bonus":"—","damage":"1d6 impacto","traits":["Ágil"]},{"name":"Pescoço","bonus":"—","damage":"1d4 impacto","traits":["Não-Letal","Alcance 10 pés"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 92, '{"hp_base":8,"support_benefit":"Enquanto montado na girafa, você não precisa de uma mão livre para Empurrar e um inimigo Empurrado move 10 pés (15 pés em sucesso crítico).","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.kangaroo', 'Canguru', 'Kangaroo', 'Canguro', 'Companheiro saltador que combina mobilidade e ataques corporais.', 'A leaping companion combining mobility and natural attacks.', 'Compañero saltador que combina movilidad y ataques naturales.', 'animal_companion', 'Pequeno', '30 pés', '[{"name":"Pé","bonus":"—","damage":"1d6 impacto","traits":["Ágil"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 92, '{"hp_base":6,"support_benefit":"Até o início do seu próximo turno, o canguru conta como estando em seu espaço ou em um espaço vazio a até 5 pés para determinar flanqueamento.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.mongoose', 'Mangusto', 'Mongoose', 'Mangosta', 'Companheiro ágil que protege criaturas próximas contra flanqueamento.', 'An agile companion that protects nearby creatures from flanking.', 'Compañero ágil que protege a criaturas cercanas contra el flanqueo.', 'animal_companion', 'Pequeno', '25 pés, escavação 10 pés', '[{"name":"Mandíbulas","bonus":"—","damage":"1d6 perfurante","traits":["Acurada"]},{"name":"Garra","bonus":"—","damage":"1d4 cortante","traits":["Ágil","Acurada"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 93, '{"hp_base":4,"support_benefit":"Até o fim do seu próximo turno, criaturas adjacentes ao mangusto não podem flanquear você.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.salamander', 'Salamandra', 'Salamander', 'Salamandra', 'Companheiro anfíbio que secreta veneno e nada em águas rasas.', 'An amphibious companion that secretes poison and swims in shallow water.', 'Compañero anfibio que secreta veneno y nada en aguas poco profundas.', 'animal_companion', 'Pequeno', '20 pés, natação 10 pés', '[{"name":"Cauda","bonus":"—","damage":"1d6 impacto","traits":[]},{"name":"Mandíbulas","bonus":"—","damage":"1d4 perfurante","traits":[]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 93, '{"hp_base":6,"support_benefit":"Até o início do seu próximo turno, uma criatura adjacente que atingir você ou a salamandra sofre 1d6 de dano de veneno.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.giant_eel', 'Enguia Gigante', 'Giant Eel', 'Anguila gigante', 'Companheiro aquático avançado que cria ângulos inesperados para flanquear.', 'An advanced aquatic companion that creates unexpected flanking positions.', 'Compañero acuático avanzado que crea posiciones inesperadas de flanqueo.', 'animal_companion', 'Grande', '10 pés, natação 40 pés', '[{"name":"Mandíbulas","bonus":"—","damage":"1d8 perfurante","traits":[]}]'::jsonb, ARRAY[]::text[], 'uncommon', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 94, '{"hp_base":4,"support_benefit":"Até o início do seu próximo turno, para determinar flanqueamento a enguia pode contar como estando em seu espaço ou em um espaço vazio a até 10 pés, escolhendo um espaço diferente a cada ataque.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.giant_frog', 'Sapo Gigante', 'Giant Frog', 'Rana gigante', 'Companheiro anfíbio avançado com língua de longo alcance e controle de reações.', 'An advanced amphibious companion with a long-range tongue and reaction control.', 'Compañero anfibio avanzado con lengua de largo alcance y control de reacciones.', 'animal_companion', 'Grande', '20 pés, escalada 20 pés, natação 25 pés', '[{"name":"Mandíbulas","bonus":"—","damage":"1d8 perfurante","traits":[]},{"name":"Língua","bonus":"—","damage":"1d4 impacto","traits":["Alcance 15 pés"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 94, '{"hp_base":6,"support_benefit":"Até o início do seu próximo turno, quando você atingir com sucesso uma criatura ameaçada pelo sapo, ela não pode usar reações acionadas por suas ações, a menos que seu nível seja maior que o seu.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.hippogriff', 'Hipogrifo', 'Hippogriff', 'Hipogrifo', 'Companheiro voador avançado para montaria e ataques aéreos.', 'An advanced flying companion for mounted and aerial attacks.', 'Compañero volador avanzado para ataques montados y aéreos.', 'animal_companion', 'Grande', '30 pés, voo 60 pés', '[{"name":"Bico","bonus":"—","damage":"1d6 perfurante","traits":[]},{"name":"Garra","bonus":"—","damage":"1d4 cortante","traits":["Ágil"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 95, '{"hp_base":8,"support_benefit":"Enquanto montado e após mover-se 10 pés ou mais antes de um Golpe corpo a corpo, adicione ao dano um bônus de circunstância igual ao dobro dos dados de dano da arma.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.riding_tarantula', 'Tarântula de Montaria', 'Riding Tarantula', 'Tarántula de monta', 'Companheiro aracnídeo avançado que escala e perturba ações de concentração.', 'An advanced arachnid companion that climbs and disrupts concentrate actions.', 'Compañero arácnido avanzado que trepa y perturba acciones de concentración.', 'animal_companion', 'Grande', '30 pés, escalada 30 pés', '[{"name":"Presas","bonus":"—","damage":"1d6 perfurante mais veneno","traits":["Acurada"]},{"name":"Perna","bonus":"—","damage":"1d4 perfurante","traits":["Ágil","Acurada"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 96, '{"hp_base":4,"support_benefit":"Até o início do seu próximo turno, uma criatura atingida por seu Golpe que esteja no alcance da tarântula deve passar em um teste simples CD 5 ao usar uma ação de concentração ou perde a ação.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.roc', 'Roc', 'Roc', 'Roc', 'Companheiro voador colossal avançado capaz de carregar criaturas e empurrá-las.', 'A colossal advanced flying companion able to carry and push creatures.', 'Compañero volador colosal avanzado capaz de transportar y empujar criaturas.', 'animal_companion', 'Enorme', '15 pés, voo 60 pés', '[{"name":"Bico","bonus":"—","damage":"1d10 perfurante","traits":[]},{"name":"Garra","bonus":"—","damage":"1d8 cortante mais Agarrar","traits":["Ágil"]}]'::jsonb, ARRAY[]::text[], 'uncommon', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 96, '{"hp_base":8,"support_benefit":"Até o início do seu próximo turno, seus Golpes que causam dano a uma criatura ameaçada pelo roc empurram o alvo 5 pés para longe do roc.","advanced_maneuver":null,"needs_review":false}'::jsonb),
